window.EXTRA.ican = [
  { id:"pq_ican_fa", name:"ICAN — Financial Accounting & Reporting", emoji:"🧮", cards:[
    { t:"mc", q:"In double-entry bookkeeping, what is the effect on the accounting equation when a business buys equipment for cash?", a:"One asset increases and another asset decreases, so total assets are unchanged", w:["Total assets increase and liabilities increase","Total assets decrease and equity decreases","Liabilities increase and equity decreases"], e:"Cash falls while equipment rises, so the equation Assets = Liabilities + Equity stays balanced." },
    { t:"mc", q:"Which accounting concept requires that revenue and the expenses incurred to earn it be reported in the same period?", a:"Matching (accruals) concept", w:["Going concern concept","Prudence concept","Materiality concept"], e:"The matching concept aligns expenses with the revenues they help generate within the same period." },
    { t:"tf", q:"A debit entry increases an asset account and a liability account equally.", a:"False", e:"A debit increases assets and expenses but decreases liabilities, equity and income." },
    { t:"mc", q:"What does a credit balance on the trial balance most commonly represent?", a:"Liabilities, equity and income items", w:["Assets and expenses only","Assets and liabilities only","Expenses and drawings"], e:"Liabilities, capital and income normally carry credit balances, while assets and expenses carry debit balances." },
    { t:"type", q:"The financial statement that reports an entity's assets, liabilities and equity at a single point in time is the statement of financial ______.", a:"position", accepts:["position (balance sheet)","financial position"], e:"The statement of financial position (balance sheet) shows balances at a reporting date." },
    { t:"mc", q:"Under the historical cost convention, non-current assets are initially recorded at:", a:"The cost incurred to acquire and bring them into use", w:["Current market value at year end","Net realisable value","Estimated replacement cost"], e:"Historical cost records assets at their original acquisition cost plus costs of bringing them into use." },
    { t:"mc", q:"A suspense account is opened mainly to:", a:"Temporarily hold a difference until errors are found and corrected", w:["Record only cash transactions","Replace the sales ledger control account","Record permanent capital contributions"], e:"A suspense account holds an unexplained difference in the trial balance until the cause is identified." },
    { t:"tf", q:"Errors of omission, where a transaction is completely left out of the books, do not affect trial balance agreement.", a:"True", e:"Because both the debit and credit are omitted, the trial balance still balances despite the error." },
    { t:"mc", q:"Which IFRS standard governs the recognition and measurement of property, plant and equipment?", a:"IAS 16", w:["IAS 2","IFRS 15","IAS 38"], e:"IAS 16 deals with property, plant and equipment, including cost, depreciation and revaluation." },
    { t:"mc", q:"Under IAS 2, inventories are measured at:", a:"The lower of cost and net realisable value", w:["Cost less accumulated depreciation","Selling price less normal profit margin","Replacement cost at year end"], e:"IAS 2 requires inventory to be carried at the lower of cost and net realisable value." },
    { t:"type", q:"Under IAS 16, the systematic allocation of a depreciable asset's cost over its useful life is called ______.", a:"depreciation", accepts:["depreciation expense"], e:"Depreciation spreads the cost of a tangible non-current asset over the periods it benefits." },
    { t:"mc", q:"The core principle of IFRS 15 is that revenue is recognised when:", a:"Control of goods or services is transferred to the customer", w:["Cash is received from the customer","The sales invoice is raised","The order is received from the customer"], e:"IFRS 15 recognises revenue as performance obligations are satisfied by transferring control to the customer." },
    { t:"mc", q:"Under IAS 1, which of the following is NOT one of the complete set of financial statements?", a:"Directors' detailed budget forecast", w:["Statement of financial position","Statement of cash flows","Statement of changes in equity"], e:"A budget forecast is not a required IFRS financial statement; the others are part of the complete set." },
    { t:"tf", q:"The going concern assumption presumes an entity will continue operating for the foreseeable future.", a:"True", e:"Going concern assumes the entity will not be liquidated or significantly curtail operations in the near term." },
    { t:"mc", q:"In a statement of cash flows under IAS 7, interest paid is typically classified under which activity by most entities?", a:"Operating or financing activities", w:["Investing activities only","Equity activities only","Tax activities only"], e:"IAS 7 allows interest paid to be classified as operating or financing, applied consistently." },
    { t:"mc", q:"Goodwill arising on a business combination under IFRS 3 is:", a:"Not amortised but tested annually for impairment", w:["Amortised over five years","Written off immediately to equity","Depreciated over twenty years"], e:"Under IFRS, goodwill is not amortised but is subject to annual impairment testing." },
    { t:"type", q:"A provision is recognised under IAS 37 only when there is a present obligation, a probable outflow, and a reliable ______ of the amount.", a:"estimate", accepts:["estimation","measurement"], e:"IAS 37 requires a present obligation, probable outflow and a reliable estimate before a provision is recognised." },
    { t:"mc", q:"The current ratio is calculated as:", a:"Current assets divided by current liabilities", w:["Current liabilities divided by current assets","Inventory divided by current liabilities","Current assets divided by total assets"], e:"The current ratio measures short-term liquidity as current assets over current liabilities." },
    { t:"mc", q:"If a company has gross profit of 400 and sales of 1,000, the gross profit margin is:", a:"40 percent", w:["25 percent","60 percent","250 percent"], e:"Gross profit margin equals gross profit divided by sales, 400 over 1,000, which is 40 percent." },
    { t:"tf", q:"A bank reconciliation explains the difference between the cash book balance and the bank statement balance.", a:"True", e:"The reconciliation accounts for timing differences and errors between the two records." },
    { t:"mc", q:"Under the accruals concept, rent paid in advance at year end is treated as:", a:"A prepayment shown as a current asset", w:["An accrued expense and current liability","Income for the current year","A reduction of capital"], e:"Rent paid in advance relates to a future period and is carried forward as a prepayment asset." },
    { t:"mc", q:"The double-entry to record depreciation charged for the year is:", a:"Debit depreciation expense, credit accumulated depreciation", w:["Debit asset cost, credit cash","Debit accumulated depreciation, credit asset cost","Debit cash, credit depreciation expense"], e:"Depreciation expense is debited and the accumulated depreciation provision is credited each period." },
    { t:"type", q:"The accounting record that brings together total debit and credit balances to check arithmetical accuracy is the trial ______.", a:"balance", accepts:["balance (trial balance)"], e:"The trial balance lists all ledger balances to confirm total debits equal total credits." },
    { t:"mc", q:"Which body issues International Financial Reporting Standards adopted in Nigeria?", a:"The International Accounting Standards Board", w:["The Financial Reporting Council of Nigeria","The Federal Inland Revenue Service","The Securities and Exchange Commission"], e:"IFRS are issued by the IASB; the FRC oversees their adoption and enforcement in Nigeria." },
    { t:"mc", q:"A contingent liability under IAS 37 is normally:", a:"Disclosed in the notes rather than recognised, unless an outflow is remote", w:["Recognised as a full liability in all cases","Recorded directly in equity","Treated as a current asset"], e:"A contingent liability is disclosed unless the possibility of outflow is remote, when no disclosure is needed." }
  ]},
  { id:"pq_ican_tax", name:"ICAN — Taxation", emoji:"⚖️", cards:[
    { t:"mc", q:"What is the standard rate of Value Added Tax in Nigeria?", a:"7.5 percent", w:["5 percent","10 percent","15 percent"], e:"The VAT rate in Nigeria was increased to 7.5 percent by the Finance Act 2019." },
    { t:"mc", q:"Which body is responsible for assessing and collecting Companies Income Tax in Nigeria?", a:"The Federal Inland Revenue Service", w:["The State Internal Revenue Service","The Central Bank of Nigeria","The Nigerian Customs Service"], e:"The FIRS administers federal taxes such as Companies Income Tax and VAT." },
    { t:"mc", q:"PAYE (Pay As You Earn) tax on employment income is generally administered and collected by:", a:"The relevant State Internal Revenue Service", w:["The Federal Inland Revenue Service","The Nigeria Deposit Insurance Corporation","The Corporate Affairs Commission"], e:"Personal Income Tax, including PAYE, is collected by State Internal Revenue Services for residents of the state." },
    { t:"mc", q:"Under the Companies Income Tax regime, the standard rate applicable to large companies is:", a:"30 percent", w:["20 percent","10 percent","7.5 percent"], e:"Large companies, generally those above the turnover threshold, are taxed at 30 percent." },
    { t:"tf", q:"Under the Finance Act framework, small companies with turnover below the statutory threshold are charged Companies Income Tax at zero percent.", a:"True", e:"Small companies whose turnover falls under the small-company threshold enjoy a 0 percent CIT rate." },
    { t:"mc", q:"In Nigerian company taxation, capital allowances are granted in place of:", a:"Accounting depreciation, which is disallowed for tax", w:["Interest expense","Bad debts written off","Salaries and wages"], e:"Depreciation is added back and capital allowances are granted instead on qualifying capital expenditure." },
    { t:"type", q:"Tax deducted at source from certain payments such as dividends, rent and contracts, creditable against the recipient's final tax, is called ______ tax.", a:"withholding", accepts:["withholding (WHT)","WHT"], e:"Withholding tax is an advance payment of income tax deducted at source from specified payments." },
    { t:"mc", q:"Which of the following supplies is typically exempt from VAT in Nigeria?", a:"Basic food items and medical services", w:["Imported luxury vehicles","Professional consultancy services","Hotel accommodation"], e:"Items such as basic food, medical and pharmaceutical products and educational materials are VAT exempt." },
    { t:"mc", q:"Personal Income Tax in Nigeria is governed primarily by which legislation?", a:"The Personal Income Tax Act", w:["The Companies Income Tax Act","The Petroleum Profits Tax Act","The Stamp Duties Act"], e:"The Personal Income Tax Act governs the taxation of individuals, including PAYE on employment income." },
    { t:"tf", q:"VAT in Nigeria is a tax on the final consumer collected at each stage of the supply chain.", a:"True", e:"VAT is a consumption tax borne by the final consumer but collected and remitted by registered businesses along the chain." },
    { t:"mc", q:"The Tertiary Education Tax is imposed on the assessable profits of:", a:"Nigerian resident companies", w:["Individual employees under PAYE","Non-resident individuals only","Unregistered partnerships only"], e:"Tertiary Education Tax is charged on the assessable profits of companies registered in Nigeria." },
    { t:"mc", q:"Which of the following is an example of a direct tax?", a:"Companies Income Tax", w:["Value Added Tax","Customs import duty","Excise duty"], e:"A direct tax such as CIT is borne by the person assessed, unlike indirect consumption taxes." },
    { t:"type", q:"The first capital allowance granted in the year an asset is acquired, in addition to annual allowance, is the ______ allowance.", a:"initial", accepts:["initial allowance"], e:"Initial allowance is a one-off allowance granted in the year qualifying capital expenditure is incurred." },
    { t:"mc", q:"A balancing charge arises on disposal of a qualifying asset when:", a:"Sale proceeds exceed the tax written down value", w:["Sale proceeds are below the tax written down value","No capital allowances were ever claimed","The asset is scrapped for nil value"], e:"A balancing charge claws back excess allowances when proceeds exceed the tax written down value." },
    { t:"mc", q:"Under the residence rule for Personal Income Tax, an individual is generally taxed by the state in which they:", a:"Are resident on the first day of the year of assessment", w:["Were born regardless of current residence","Hold a bank account","Own any property"], e:"The relevant tax authority is usually that of the individual's state of residence at the start of the year of assessment." },
    { t:"tf", q:"Companies Income Tax is assessed on a preceding year basis for ongoing businesses in Nigeria.", a:"True", e:"For continuing businesses, CIT is generally assessed on the profits of the accounting period ending in the preceding year." },
    { t:"mc", q:"Input VAT recoverable by a registered business is VAT:", a:"Paid on purchases used to make taxable supplies", w:["Charged to customers on sales","Paid on staff entertainment only","On exempt supplies only"], e:"Input VAT on goods and services used for taxable supplies can be offset against output VAT." },
    { t:"mc", q:"Which of these is generally a disallowable expense in computing taxable profits?", a:"Depreciation of fixed assets", w:["Salaries to staff","Rent of business premises","Repairs to plant"], e:"Depreciation is disallowed and replaced by capital allowances; ordinary business expenses are deductible." },
    { t:"type", q:"The federal agency that administers Companies Income Tax and VAT is the Federal Inland Revenue ______.", a:"Service", accepts:["Service (FIRS)","FIRS"], e:"The Federal Inland Revenue Service is the federal tax administration body in Nigeria." },
    { t:"mc", q:"The basis of charge to VAT on imported goods is the:", a:"Value of the goods including duty at the point of importation", w:["Cost price excluding all duties","Selling price in the country of origin","Annual turnover of the importer"], e:"VAT on imports is computed on the import value, which includes applicable customs duty and charges." }
  ]},
  { id:"pq_ican_audit", name:"ICAN — Audit & Assurance", emoji:"🔍", cards:[
    { t:"mc", q:"The primary objective of an external audit of financial statements is to:", a:"Express an opinion on whether the statements give a true and fair view", w:["Detect and prevent all fraud and error","Prepare the financial statements for the directors","Guarantee the future solvency of the company"], e:"The external auditor gives reasonable assurance that the statements are free from material misstatement." },
    { t:"mc", q:"Which type of audit opinion is issued when financial statements are materially misstated and the effect is pervasive?", a:"Adverse opinion", w:["Unqualified opinion","Qualified opinion","Disclaimer of opinion"], e:"An adverse opinion is given when misstatements are both material and pervasive to the statements." },
    { t:"tf", q:"A disclaimer of opinion is issued when the auditor cannot obtain sufficient appropriate evidence and the possible effects are pervasive.", a:"True", e:"A disclaimer arises from a pervasive limitation of scope that prevents forming an opinion." },
    { t:"mc", q:"Audit risk is best described as the risk that:", a:"The auditor expresses an inappropriate opinion on materially misstated statements", w:["The client becomes insolvent after the audit","The audit fee is not recovered","Staff make arithmetical errors in the file"], e:"Audit risk is the risk of giving a wrong opinion when the financial statements are materially misstated." },
    { t:"mc", q:"The audit risk model is usually expressed as:", a:"Inherent risk multiplied by control risk multiplied by detection risk", w:["Inherent risk plus materiality","Control risk minus detection risk","Business risk divided by audit fee"], e:"Audit risk is the product of inherent risk, control risk and detection risk." },
    { t:"type", q:"The concept that an item is significant enough to influence the decisions of users of the financial statements is called ______.", a:"materiality", accepts:["material"], e:"Materiality determines the nature and extent of audit procedures and what misstatements matter." },
    { t:"mc", q:"Which fundamental ethical principle requires an auditor to be straightforward and honest in all professional relationships?", a:"Integrity", w:["Confidentiality","Professional competence","Objectivity"], e:"Integrity, under the IESBA Code, requires honesty and straightforwardness in professional dealings." },
    { t:"mc", q:"A self-review threat to auditor independence arises when:", a:"The auditor reviews work that they themselves previously performed", w:["The auditor is offered a small gift","An audit junior lacks experience","The client delays providing records"], e:"A self-review threat occurs when the auditor evaluates their own previous judgements or work." },
    { t:"tf", q:"Substantive procedures are designed to detect material misstatements at the assertion level.", a:"True", e:"Substantive procedures, including tests of detail and analytical procedures, address misstatements in assertions." },
    { t:"mc", q:"Tests of controls are performed to:", a:"Evaluate the operating effectiveness of internal controls", w:["Confirm year-end bank balances","Value closing inventory","Recalculate the tax charge"], e:"Tests of controls assess whether controls operated effectively to prevent or detect misstatements." },
    { t:"mc", q:"Which of the following provides the most reliable audit evidence?", a:"Evidence obtained directly by the auditor from an independent external source", w:["Oral representations from management","Photocopies provided by the client","Internally generated documents only"], e:"External, independent evidence obtained directly by the auditor is generally the most reliable." },
    { t:"type", q:"A written confirmation obtained directly from a third party such as a customer or bank is known as an external ______.", a:"confirmation", accepts:["confirmation (circularisation)"], e:"External confirmations provide reliable evidence sourced directly from independent third parties." },
    { t:"mc", q:"Professional scepticism requires the auditor to:", a:"Maintain a questioning mind and critically assess evidence", w:["Assume management is always dishonest","Accept all client explanations without question","Audit only the cash balance"], e:"Professional scepticism means remaining alert to conditions indicating possible misstatement." },
    { t:"mc", q:"An auditor's report that contains no reservations about the financial statements expresses a(n):", a:"Unmodified (unqualified) opinion", w:["Qualified opinion","Adverse opinion","Disclaimer of opinion"], e:"An unmodified opinion states the financial statements give a true and fair view without reservation." },
    { t:"tf", q:"The directors, not the external auditor, are responsible for preparing the financial statements.", a:"True", e:"Preparation of the financial statements is a directors' responsibility; the auditor reports an opinion on them." },
    { t:"mc", q:"Which threat to independence arises when audit fees from one client form a large proportion of total firm income?", a:"Self-interest threat", w:["Advocacy threat","Familiarity threat","Intimidation threat"], e:"Fee dependence creates a self-interest threat because the firm may fear losing important income." },
    { t:"mc", q:"Sufficiency of audit evidence refers to the:", a:"Quantity of evidence obtained", w:["Quality and relevance of evidence","Cost of obtaining evidence","Speed of obtaining evidence"], e:"Sufficiency concerns quantity, while appropriateness concerns the quality and relevance of evidence." },
    { t:"mc", q:"An engagement letter is important because it:", a:"Sets out the agreed terms and scope of the audit engagement", w:["Guarantees an unqualified opinion","Replaces the audit report","Fixes the share price of the client"], e:"The engagement letter documents the scope, responsibilities and terms agreed with the client." }
  ]},
  { id:"pq_ican_cost", name:"ICAN — Costing & Management", emoji:"📊", cards:[
    { t:"mc", q:"Under marginal costing, the contribution per unit is calculated as:", a:"Selling price per unit less variable cost per unit", w:["Selling price per unit less total fixed cost","Fixed cost per unit less variable cost","Total cost less selling price"], e:"Contribution is selling price minus variable cost, available to cover fixed costs and profit." },
    { t:"mc", q:"The break-even point in units is found by dividing fixed costs by:", a:"Contribution per unit", w:["Selling price per unit","Variable cost per unit","Total cost per unit"], e:"Break-even units equal total fixed costs divided by contribution per unit." },
    { t:"mc", q:"If fixed costs are 60,000 and contribution per unit is 30, the break-even point is:", a:"2,000 units", w:["1,800 units","3,000 units","20,000 units"], e:"Break-even equals 60,000 divided by 30, which is 2,000 units." },
    { t:"tf", q:"Under marginal costing, fixed manufacturing overheads are treated as period costs and charged in full against the period.", a:"True", e:"Marginal costing writes off fixed overheads as period costs rather than absorbing them into units." },
    { t:"mc", q:"The margin of safety is the difference between:", a:"Actual or budgeted sales and break-even sales", w:["Fixed cost and variable cost","Selling price and variable cost","Total revenue and total contribution"], e:"Margin of safety shows how far sales can fall before reaching break-even." },
    { t:"mc", q:"In absorption costing, the over- or under-absorption of overhead arises when:", a:"Actual overhead differs from absorbed overhead based on a predetermined rate", w:["Direct materials price changes","Sales volume equals budget exactly","Variable costs are ignored"], e:"Using a predetermined rate, differences between actual and absorbed overhead cause over or under absorption." },
    { t:"type", q:"The costing method that absorbs both fixed and variable production overheads into unit cost is ______ costing.", a:"absorption", accepts:["absorption (full)","full"], e:"Absorption costing includes fixed and variable production overheads in the cost of each unit." },
    { t:"mc", q:"A favourable direct material price variance occurs when:", a:"The actual price paid is lower than the standard price", w:["More material is used than standard","The actual price paid is higher than standard","Output is below budget"], e:"Paying less than standard price for materials gives a favourable price variance." },
    { t:"mc", q:"The direct labour efficiency variance measures the difference between:", a:"Standard hours for actual output and actual hours worked, valued at standard rate", w:["Standard rate and actual rate paid","Budgeted and actual fixed overhead","Standard and actual material usage"], e:"Labour efficiency compares hours allowed for output with hours actually worked at the standard rate." },
    { t:"tf", q:"A flexible budget is adjusted to reflect the actual level of activity achieved.", a:"True", e:"A flexible budget restates budgeted costs and revenues for the actual activity level, aiding control." },
    { t:"mc", q:"Which of the following is a relevant cost for decision making?", a:"A future cash flow that differs between alternatives", w:["A sunk cost already incurred","An apportioned head office cost that will not change","Historical depreciation on existing assets"], e:"Relevant costs are future, incremental cash flows that change with the decision." },
    { t:"mc", q:"A sunk cost is best described as a cost that:", a:"Has already been incurred and cannot be changed by a future decision", w:["Will be incurred only if a project proceeds","Varies directly with output","Is avoidable in the next period"], e:"Sunk costs are past and unavoidable, so they are irrelevant to current decisions." },
    { t:"type", q:"The point at which total revenue equals total cost, giving neither profit nor loss, is the ______ point.", a:"break-even", accepts:["breakeven","break even"], e:"At the break-even point total contribution exactly covers total fixed costs." },
    { t:"mc", q:"The contribution to sales (C/S) ratio is used to calculate:", a:"Break-even revenue and the effect of sales mix changes", w:["The depreciation charge","The corporation tax liability","The dividend per share"], e:"The C/S ratio expresses contribution as a fraction of sales, useful for break-even revenue calculations." },
    { t:"mc", q:"A zero-based budget requires that:", a:"Each cost is justified from scratch every period", w:["Last year's budget is increased by inflation","Only capital costs are budgeted","No budget is prepared for fixed costs"], e:"Zero-based budgeting justifies every expenditure afresh rather than building on prior budgets." },
    { t:"mc", q:"In a limiting factor (scarce resource) decision, products should be ranked by:", a:"Contribution per unit of the limiting factor", w:["Total contribution per product line","Selling price per unit","Variable cost per unit"], e:"Maximising contribution per unit of the scarce resource optimises total contribution." },
    { t:"tf", q:"Under marginal costing, when production exceeds sales, reported profit is lower than under absorption costing.", a:"True", e:"Marginal costing does not carry fixed overhead in closing inventory, so profit is lower when inventory rises." },
    { t:"mc", q:"A cost that contains both a fixed and a variable element is described as a:", a:"Semi-variable (mixed) cost", w:["Purely variable cost","Purely fixed cost","Sunk cost"], e:"Semi-variable costs have a fixed base plus a portion that varies with activity, such as a phone bill." },
    { t:"mc", q:"The high-low method is used to:", a:"Separate a semi-variable cost into fixed and variable components", w:["Value closing inventory at market price","Allocate joint costs to by-products","Compute the internal rate of return"], e:"The high-low method estimates the variable rate and fixed cost from the highest and lowest activity levels." },
    { t:"type", q:"A budget that summarises all functional budgets into a projected income statement and statement of financial position is the ______ budget.", a:"master", accepts:["master budget"], e:"The master budget consolidates departmental budgets into overall financial statements." }
  ]},
  { id:"pq_ican_law", name:"ICAN — Law, Governance & Ethics", emoji:"📜", cards:[
    { t:"mc", q:"In Nigeria, companies are incorporated and regulated principally under which legislation?", a:"The Companies and Allied Matters Act", w:["The Investments and Securities Act","The Banks and Other Financial Institutions Act","The Personal Income Tax Act"], e:"The Companies and Allied Matters Act, as amended in 2020, governs company formation and administration in Nigeria." },
    { t:"mc", q:"Which body is responsible for the registration of companies in Nigeria?", a:"The Corporate Affairs Commission", w:["The Securities and Exchange Commission","The Central Bank of Nigeria","The Federal Inland Revenue Service"], e:"The Corporate Affairs Commission administers company registration under CAMA." },
    { t:"tf", q:"A registered company is a separate legal person distinct from its members.", a:"True", e:"The principle of separate legal personality, from Salomon v Salomon, treats a company as distinct from its owners." },
    { t:"mc", q:"For a valid simple contract to exist, which of the following is essential?", a:"Offer, acceptance, consideration and intention to create legal relations", w:["Only an offer and acceptance","Only a written document signed by both parties","A government licence in all cases"], e:"A binding contract requires offer, acceptance, consideration, capacity and intention to create legal relations." },
    { t:"mc", q:"Consideration in contract law refers to:", a:"Something of value exchanged between the parties", w:["The motive behind the contract","A written signature only","The court fee for enforcement"], e:"Consideration is the price each party pays for the other's promise, an essential element of a simple contract." },
    { t:"type", q:"The doctrine that limits a company's actions to those within the objects in its constitution is the doctrine of ______ vires.", a:"ultra", accepts:["ultra vires"], e:"Acts beyond a company's stated objects were historically described as ultra vires, though CAMA has relaxed this." },
    { t:"mc", q:"The minimum number of directors required for a public company under CAMA 2020 is:", a:"Two, with a requirement of at least three for a public company", w:["Five","Ten","Twenty"], e:"CAMA requires a private company to have at least one director and a public company at least three." },
    { t:"mc", q:"Corporate governance is best described as:", a:"The system by which companies are directed and controlled", w:["The day-to-day bookkeeping of a company","The marketing strategy of a company","The tax planning of a company"], e:"Corporate governance concerns the structures and processes for directing and controlling a company." },
    { t:"tf", q:"Separating the roles of board chairman and chief executive officer is widely regarded as good corporate governance practice.", a:"True", e:"Splitting the two roles avoids concentration of power and strengthens board oversight." },
    { t:"mc", q:"An audit committee's main role in corporate governance is to:", a:"Oversee financial reporting and the work of internal and external auditors", w:["Set the dividend policy alone","Manage daily operations","Approve all customer contracts"], e:"The audit committee strengthens oversight of financial reporting, controls and the audit process." },
    { t:"mc", q:"Which fundamental principle of professional ethics requires members not to disclose client information acquired in the course of work?", a:"Confidentiality", w:["Integrity","Objectivity","Professional behaviour"], e:"Confidentiality requires members to respect and not improperly disclose information obtained at work." },
    { t:"type", q:"A director's duty to act honestly in what they consider to be the interests of the company is a fiduciary ______.", a:"duty", accepts:["duty (fiduciary)"], e:"Directors owe fiduciary duties, including good faith, to act in the best interests of the company." },
    { t:"mc", q:"The principle of objectivity requires a professional accountant to:", a:"Not allow bias, conflict of interest or undue influence to override judgements", w:["Always agree with the client","Keep all fees confidential","Accept every engagement offered"], e:"Objectivity means professional judgements must be free from bias and improper influence." },
    { t:"mc", q:"A breach of contract entitles the innocent party primarily to claim:", a:"Damages to compensate for the loss suffered", w:["Imprisonment of the other party","Automatic ownership of the other party's company","A criminal fine payable to them"], e:"The usual remedy for breach of contract is damages to put the injured party in the position as if performed." },
    { t:"tf", q:"Professional behaviour requires accountants to comply with relevant laws and avoid conduct that discredits the profession.", a:"True", e:"The principle of professional behaviour demands compliance with laws and avoidance of discrediting conduct." },
    { t:"mc", q:"In a partnership, partners are generally liable for the firm's debts on a basis that is:", a:"Joint and several and unlimited", w:["Limited to their original capital only","Borne solely by the senior partner","Limited to one year of profits"], e:"Ordinary partners share unlimited joint and several liability for the firm's debts." },
    { t:"mc", q:"Which Nigerian body issues the codes of corporate governance and oversees financial reporting standards for public interest entities?", a:"The Financial Reporting Council of Nigeria", w:["The Corporate Affairs Commission","The Nigerian Stock Exchange Council","The National Insurance Commission"], e:"The Financial Reporting Council of Nigeria issues governance codes and oversees reporting standards." }
  ]}
];
window.EXTRA = window.EXTRA || {};
window.EXTRA.cibn = [
  { id:"pq_cibn_ops", name:"CIBN — Banking Operations", emoji:"🏦", cards:[
    { t:"mc", q:"Which account type is primarily designed for frequent transactions and typically allows cheque withdrawals but usually earns little or no interest?", a:"Current account", w:["Fixed deposit account","Savings account","Domiciliary account"], e:"A current account supports frequent payments and cheque issuance, prioritising liquidity over interest." },
    { t:"mc", q:"A fixed deposit (term deposit) account is best described as one that:", a:"Locks funds for an agreed period in exchange for higher interest", w:["Allows unlimited daily withdrawals","Pays no interest at all","Can only be opened by companies"], e:"Fixed deposits tie up funds for a set tenor and reward the customer with a higher rate." },
    { t:"mc", q:"A domiciliary account in Nigeria is used to hold:", a:"Foreign currency such as US dollars or pounds", w:["Only naira coins","Shares and bonds","Pension contributions only"], e:"Domiciliary accounts let customers hold and transact in foreign currencies." },
    { t:"tf", q:"A dormant account is one that has had no customer-initiated transaction for a defined period.", a:"True", e:"Accounts inactive for a set period are classified as dormant and may require reactivation." },
    { t:"type", q:"The process by which a bank confirms a customer identity and source of funds before account opening is called ______.", a:"KYC", accepts:["Know Your Customer","know your customer"], e:"Know Your Customer (KYC) is a core compliance step in onboarding." },
    { t:"mc", q:"Which document is the formal instruction allowing a bank to know who can operate a company account?", a:"Mandate (account mandate)", w:["Memorandum of association only","Trial balance","Bank statement"], e:"The mandate specifies authorised signatories and operating instructions for the account." },
    { t:"mc", q:"When a bank reconciles a customer ledger balance with the bank statement, differences such as unpresented cheques are shown in a:", a:"Bank reconciliation statement", w:["Profit and loss account","Cash flow forecast","Letter of credit"], e:"A reconciliation statement explains timing differences between the cashbook and bank records." },
    { t:"tf", q:"A standing order is a customer instruction to pay a fixed amount to a beneficiary at regular intervals.", a:"True", e:"Standing orders automate fixed recurring payments such as rent or subscriptions." },
    { t:"mc", q:"A direct debit differs from a standing order mainly because the amount and timing are:", a:"Controlled by the beneficiary within an agreed mandate", w:["Always fixed by the payer","Never variable","Set only by the central bank"], e:"In a direct debit the payee initiates collections, which may vary, under the customer mandate." },
    { t:"mc", q:"The term float in banking operations refers to:", a:"Funds in transit between deposit and final clearance", w:["A banks total share capital","The interest earned on loans","A customer overdraft limit"], e:"Float is money that has been deposited but not yet fully cleared and available." },
    { t:"type", q:"A ______ account requires two or more persons and an instruction on how it is to be operated, such as either or both to sign.", a:"joint", accepts:["Joint"], e:"Joint accounts are held by more than one person under an agreed signing mandate." },
    { t:"mc", q:"Which of the following is a primary function of a commercial bank?", a:"Accepting deposits and granting loans", w:["Printing the national currency","Setting the monetary policy rate","Insuring all bank deposits directly"], e:"Deposit-taking and lending are the core intermediation functions of commercial banks." },
    { t:"tf", q:"Maturity transformation means banks fund longer-term loans using shorter-term deposits.", a:"True", e:"Banks transform short-dated deposits into longer-dated credit, a key intermediation role." },
    { t:"mc", q:"A bank acting as an agent that collects payment on behalf of a customer for goods exported is performing a:", a:"Collection service", w:["Underwriting service","Foreign exchange dealing only","Deposit insurance function"], e:"Banks act as collecting agents to obtain payment for documents and bills on behalf of clients." },
    { t:"mc", q:"The minimum information a bank must capture under Customer Due Diligence does NOT typically include:", a:"The customer favourite colour", w:["Valid means of identification","Residential address","Source of funds"], e:"CDD focuses on identity, address and source of funds, not irrelevant personal preferences." },
    { t:"mc", q:"A teller who pays out cash against a cheque is carrying out which operation?", a:"Cash withdrawal processing", w:["Loan syndication","Bond issuance","Monetary policy setting"], e:"Paying cash against a valid cheque is a routine cash-handling operation." },
    { t:"tf", q:"A bank statement is a record of transactions on an account over a stated period.", a:"True", e:"Statements list debits, credits and balances for the period for customer review." },
    { t:"mc", q:"Anti-Money Laundering controls require banks to report transactions that are:", a:"Suspicious or above stated thresholds", w:["Only those below one naira","Made only by staff","Only cheque payments"], e:"AML rules require reporting of suspicious activity and large threshold transactions." },
    { t:"type", q:"The unique number that identifies a specific bank within the clearing and settlement system is the ______ code.", a:"sort", accepts:["sort code","bank"], e:"A sort or bank code identifies the institution for routing payments." },
    { t:"mc", q:"Which account is most suitable for a customer who wants to encourage regular saving and earn modest interest with limited withdrawals?", a:"Savings account", w:["Current account","Escrow account","Nostro account"], e:"Savings accounts reward regular deposits with interest and limited transactions." },
    { t:"mc", q:"A nostro account is best described as:", a:"An account a bank holds in a foreign currency with a correspondent bank abroad", w:["A customer overdraft account","A fixed deposit for individuals","A dormant savings account"], e:"Nostro means our account held with another bank, used in correspondent banking." },
    { t:"tf", q:"Escrow arrangements involve a neutral third party holding funds until agreed conditions are met.", a:"True", e:"Escrow protects parties by releasing funds only when contractual conditions are satisfied." }
  ]},
  { id:"pq_cibn_lend", name:"CIBN — Lending & Credit", emoji:"💳", cards:[
    { t:"mc", q:"The 5 Cs of credit are Character, Capacity, Capital, Collateral and:", a:"Conditions", w:["Currency","Compliance","Commission"], e:"Conditions covers the economic and purpose factors affecting the loan, completing the 5 Cs." },
    { t:"mc", q:"In the 5 Cs of credit, Capacity primarily measures the borrower:", a:"Ability to repay from cash flow", w:["Honesty and reputation","Physical security pledged","Net worth invested"], e:"Capacity assesses whether income or cash flow can service the debt." },
    { t:"mc", q:"Which C of credit refers to the borrower reputation, integrity and willingness to repay?", a:"Character", w:["Capital","Collateral","Conditions"], e:"Character reflects the borrowers track record and trustworthiness." },
    { t:"tf", q:"Collateral is the secondary source of repayment a bank can fall back on if the borrower defaults.", a:"True", e:"Collateral provides a fallback; cash flow remains the primary repayment source." },
    { t:"mc", q:"An overdraft facility is best described as:", a:"A short-term facility allowing a current account to go into debit up to a limit", w:["A long-term mortgage loan","A fixed instalment car loan","An equity investment"], e:"An overdraft permits drawing beyond the credit balance up to an agreed limit, usually short term." },
    { t:"mc", q:"A facility repaid in equal periodic instalments of principal and interest over a fixed term is a:", a:"Term loan", w:["Overdraft","Bridging guarantee","Bank draft"], e:"Term loans amortise over a set period through scheduled instalments." },
    { t:"mc", q:"Which security involves the lender taking the title documents of landed property as security for a loan?", a:"Legal mortgage", w:["Lien on shares","Guarantee","Negative pledge"], e:"A legal mortgage transfers an interest in land or property to the lender as security." },
    { t:"mc", q:"A pledge as a form of security typically requires:", a:"Delivery of possession of the goods to the lender", w:["Transfer of full ownership permanently","No documentation at all","Only a verbal promise"], e:"In a pledge the borrower delivers possession of movable goods while retaining ownership." },
    { t:"type", q:"A third party promise to repay a borrower debt if the borrower defaults is called a ______.", a:"guarantee", accepts:["Guarantee","guaranty"], e:"A guarantor undertakes to settle the debt if the principal borrower fails to pay." },
    { t:"mc", q:"A lien gives a bank the right to:", a:"Retain a customer property or funds until a debt is settled", w:["Sell the customer house without notice always","Print money","Set the interest rate"], e:"A lien allows retention of assets lawfully in the banks possession pending settlement." },
    { t:"tf", q:"Debenture is a common form of security taken over the assets of a company.", a:"True", e:"A debenture creates a charge, fixed or floating, over a companys assets." },
    { t:"mc", q:"A floating charge differs from a fixed charge because it:", a:"Hovers over a changing class of assets until it crystallises", w:["Is always over a single building","Cannot be enforced","Applies only to individuals"], e:"A floating charge covers assets like stock that change over time and crystallises on default." },
    { t:"mc", q:"The practice of spreading a large loan across several banks to share risk is called:", a:"Loan syndication", w:["Loan securitisation","Loan amortisation","Loan rescheduling"], e:"Syndication lets multiple lenders jointly fund a large facility and share exposure." },
    { t:"mc", q:"A non-performing loan is generally one where principal or interest is overdue by:", a:"90 days or more", w:["1 day","Exactly 30 days only","365 days only"], e:"Loans overdue by about 90 days are commonly classified as non-performing." },
    { t:"tf", q:"Credit risk is the risk that a borrower fails to meet repayment obligations.", a:"True", e:"Credit risk arises from possible default on principal or interest." },
    { t:"mc", q:"Which of these is a key purpose of a credit bureau in Nigeria?", a:"Provide borrower credit history to lenders", w:["Print currency notes","Set the monetary policy rate","Insure deposits"], e:"Credit bureaux supply credit reports that help lenders assess repayment behaviour." },
    { t:"type", q:"The maximum amount a customer is permitted to borrow on a facility is known as the credit ______.", a:"limit", accepts:["Limit"], e:"A credit limit caps the exposure the bank will allow on a facility." },
    { t:"mc", q:"Provisioning for loans means the bank:", a:"Sets aside funds to absorb expected loan losses", w:["Increases the interest rate to zero","Sells its head office","Pays dividends to borrowers"], e:"Provisions are reserves recognised against probable credit losses." },
    { t:"mc", q:"A facility used to finance the gap between buying stock and receiving sales proceeds is typically:", a:"Working capital finance", w:["A 25-year mortgage","Equity capital","A pension fund"], e:"Working capital finance bridges short-term operating cash needs." },
    { t:"mc", q:"In lending, the purpose of a moratorium is to:", a:"Allow a period before principal repayment begins", w:["Cancel the loan entirely","Double the interest immediately","Remove all security"], e:"A moratorium grants the borrower a grace period, often before principal repayments start." }
  ]},
  { id:"pq_cibn_law", name:"CIBN — Banking Law & Ethics", emoji:"📜", cards:[
    { t:"mc", q:"The relationship between a banker and a customer in respect of a credit balance is fundamentally that of:", a:"Debtor and creditor", w:["Principal and agent only","Trustee and beneficiary only","Landlord and tenant"], e:"When an account is in credit the bank is the debtor and the customer the creditor." },
    { t:"mc", q:"When a customer account is overdrawn, the banker becomes the:", a:"Creditor and the customer the debtor", w:["Trustee","Beneficiary","Bailor"], e:"An overdraft reverses the relationship, making the bank the creditor." },
    { t:"mc", q:"The duty of a banker to keep customer information confidential was established in the case of:", a:"Tournier v National Provincial and Union Bank of England", w:["Foley v Hill","Salomon v Salomon","Donoghue v Stevenson"], e:"Tournier set out the banks duty of secrecy and its recognised exceptions." },
    { t:"tf", q:"A banker duty of secrecy is absolute and has no exceptions.", a:"False", e:"Exceptions include compulsion of law, public duty, banks interest and customer consent." },
    { t:"mc", q:"A cheque is defined as a bill of exchange drawn on a banker and payable:", a:"On demand", w:["After 30 days only","At the end of the year","Only when the drawer dies"], e:"A cheque is a demand instrument drawn on a bank by the account holder." },
    { t:"mc", q:"The person who writes and signs a cheque ordering payment is the:", a:"Drawer", w:["Drawee","Payee","Endorser"], e:"The drawer is the account holder who issues and signs the cheque." },
    { t:"mc", q:"On a cheque, the bank on which it is drawn is the:", a:"Drawee", w:["Drawer","Payee","Holder in due course"], e:"The drawee is the paying bank instructed to honour the cheque." },
    { t:"type", q:"Two parallel lines across the face of a cheque, with or without words, create a ______ cheque that must be paid into an account.", a:"crossed", accepts:["Crossed","crossing"], e:"A crossing directs that the cheque be paid through an account, improving security." },
    { t:"mc", q:"Which of the following is a feature of a negotiable instrument?", a:"Title can pass freely by delivery or endorsement", w:["It can never be transferred","It must always be in foreign currency","It bears no signature"], e:"Negotiability lets a holder transfer good title by delivery and, where needed, endorsement." },
    { t:"tf", q:"A post-dated cheque should not be paid before the date written on it.", a:"True", e:"Paying before the stated date breaches the drawers mandate." },
    { t:"mc", q:"Endorsement of a cheque means:", a:"The signing on the back to transfer or negotiate it", w:["Tearing the cheque","Printing more cheques","Cancelling the account"], e:"An endorsement transfers rights in the instrument to another party." },
    { t:"mc", q:"A banker may rightfully dishonour a customer cheque when:", a:"There are insufficient funds and no agreed overdraft", w:["The customer is wealthy","The amount is small","The cheque is neatly written"], e:"Lack of funds without an arrangement is a valid reason to return a cheque unpaid." },
    { t:"mc", q:"The legal principle that a company is a separate legal person from its members came from:", a:"Salomon v Salomon and Co Ltd", w:["Tournier case","Carlill v Carbolic Smoke Ball","Rylands v Fletcher"], e:"Salomon established the separate legal personality of a registered company." },
    { t:"tf", q:"A bank owes a duty of care and skill when giving advice or references to its customer.", a:"True", e:"The banker must exercise reasonable care and skill in services rendered." },
    { t:"mc", q:"Which of these is a recognised ethical principle for banking professionals?", a:"Integrity and honesty in dealings", w:["Concealing material facts from regulators","Insider abuse of customer data","Favouring bribes"], e:"Integrity, honesty and confidentiality underpin professional banking ethics." },
    { t:"type", q:"A banker right to combine or offset balances across a customer accounts to settle a debt is the right of ______.", a:"set-off", accepts:["set off","setoff","Set-off"], e:"Set-off lets a bank combine accounts to recover what the customer owes." },
    { t:"mc", q:"A conflict of interest in banking is best managed by:", a:"Disclosure and avoidance of the conflict", w:["Ignoring it","Hiding it from supervisors","Profiting from it quietly"], e:"Ethical practice requires disclosing and avoiding conflicts of interest." },
    { t:"mc", q:"Insider abuse in a bank refers to:", a:"Misuse of position or information by staff or directors for personal gain", w:["Customers depositing cash","Paying salaries on time","Issuing genuine receipts"], e:"Insider abuse involves staff or insiders exploiting their position improperly." }
  ]},
  { id:"pq_cibn_reg", name:"CIBN — CBN, Regulation & Markets", emoji:"📈", cards:[
    { t:"mc", q:"The apex regulator of banks in Nigeria is the:", a:"Central Bank of Nigeria", w:["Nigerian Stock Exchange","Securities and Exchange Commission","Federal Inland Revenue Service"], e:"The CBN is the apex bank responsible for monetary policy and banking supervision." },
    { t:"type", q:"The rate at which the Central Bank of Nigeria lends to banks and which anchors other interest rates is the Monetary Policy ______.", a:"Rate", accepts:["rate","MPR"], e:"The Monetary Policy Rate (MPR) is the CBN benchmark policy rate." },
    { t:"mc", q:"The Cash Reserve Requirement (CRR) is best described as:", a:"The portion of bank deposits that must be kept with the central bank", w:["The interest paid on savings","The maximum loan a bank can give","The cost of printing money"], e:"CRR is the share of deposits banks must hold as reserves at the CBN." },
    { t:"mc", q:"The committee of the CBN that decides on the policy rate and other monetary tools is the:", a:"Monetary Policy Committee", w:["Board of Internal Revenue","Public Accounts Committee","Fiscal Responsibility Council"], e:"The MPC sets the MPR, CRR and related parameters at its periodic meetings." },
    { t:"mc", q:"The agency that insures deposits of licensed banks in Nigeria is the:", a:"Nigeria Deposit Insurance Corporation", w:["Central Bank of Nigeria","Securities and Exchange Commission","National Pension Commission"], e:"The NDIC provides deposit insurance and helps resolve failing banks." },
    { t:"mc", q:"Following the 2024 review, the maximum NDIC deposit insurance coverage per depositor for a Deposit Money Bank is:", a:"5 million naira", w:["500,000 naira","200,000 naira","50,000 naira"], e:"In 2024 the NDIC raised DMB coverage from 500,000 to 5,000,000 naira per depositor." },
    { t:"tf", q:"The NDIC was established to provide a safety net for depositors and contribute to financial system stability.", a:"True", e:"The NDIC protects depositors and supports stability, complementing CBN supervision." },
    { t:"mc", q:"The principal law governing the licensing and operation of banks in Nigeria is commonly abbreviated as:", a:"BOFIA", w:["NDIC Act only","CAMA only","ISA only"], e:"The Banks and Other Financial Institutions Act (BOFIA) governs bank licensing and operations." },
    { t:"mc", q:"When the CBN sells securities to reduce money supply, it is conducting:", a:"Open market operations", w:["Deposit insurance","Fiscal policy","Loan syndication"], e:"Open market operations use buying and selling of securities to manage liquidity." },
    { t:"mc", q:"A contractionary monetary policy is typically used to:", a:"Reduce inflation by tightening money supply", w:["Increase inflation deliberately","Stop all lending forever","Print unlimited money"], e:"Tightening policy curbs excess demand and helps lower inflation." },
    { t:"type", q:"Short-term debt instruments issued by the Federal Government, usually for 91, 182 or 364 days, are called Treasury ______.", a:"bills", accepts:["Bills"], e:"Treasury bills are short-dated government securities sold at a discount." },
    { t:"mc", q:"The market for short-term funds and instruments of up to one year is the:", a:"Money market", w:["Capital market","Insurance market","Commodity market"], e:"The money market deals in short-term instruments such as treasury bills and call money." },
    { t:"mc", q:"The market where long-term securities such as shares and bonds are traded is the:", a:"Capital market", w:["Money market","Foreign exchange spot market","Interbank market"], e:"The capital market handles long-term funds through equities and bonds." },
    { t:"tf", q:"A treasury bill is normally issued at a discount and redeemed at face value on maturity.", a:"True", e:"Investors buy below par and receive the full face value at maturity, earning the difference." },
    { t:"mc", q:"The Securities and Exchange Commission (SEC) is the apex regulator of the:", a:"Nigerian capital market", w:["Banking system","Insurance industry","Pension industry"], e:"The SEC regulates and supervises the Nigerian capital market." },
    { t:"mc", q:"A bond is best described as:", a:"A long-term debt instrument paying periodic interest", w:["A unit of ownership in a company","A short-term overdraft","A demand deposit"], e:"Bonds are debt securities that pay coupons and return principal at maturity." },
    { t:"mc", q:"Functions of the CBN include all of the following EXCEPT:", a:"Setting personal income tax rates", w:["Issuing the national currency","Banker to the government","Lender of last resort"], e:"Tax rates are fiscal matters; the CBN handles currency issue and monetary functions." },
    { t:"type", q:"The CBN acts as the ______ of last resort, lending to banks facing temporary liquidity shortages.", a:"lender", accepts:["Lender"], e:"As lender of last resort the CBN supports solvent banks with short-term liquidity." },
    { t:"mc", q:"Bank recapitalisation directives by the CBN in 2024 set the minimum capital for a commercial bank with international authorisation at:", a:"500 billion naira", w:["25 billion naira","50 billion naira","2 billion naira"], e:"The 2024 directive pegged international commercial banks at 500 billion naira minimum capital." },
    { t:"mc", q:"Inflation is best defined as:", a:"A sustained general rise in the price level", w:["A one-off fall in a single price","An increase in bank branches","A rise in deposit numbers"], e:"Inflation is a persistent increase in the overall level of prices." },
    { t:"tf", q:"The interbank market is where banks lend to and borrow from one another for short periods.", a:"True", e:"Banks use the interbank market to manage day-to-day liquidity needs." },
    { t:"mc", q:"The Treasury Single Account (TSA) policy is designed to:", a:"Consolidate government revenues into a unified account at the CBN", w:["Insure private deposits","Set lending rates","Replace the naira"], e:"The TSA brings government funds together for better cash and revenue management." }
  ]},
  { id:"pq_cibn_epay", name:"CIBN — E-Banking & Risk", emoji:"💻", cards:[
    { t:"mc", q:"The Bank Verification Number (BVN) in Nigeria is a unique identifier made up of:", a:"11 digits", w:["8 digits","16 digits","4 digits"], e:"The BVN is an 11-digit biometric-linked identifier for bank customers." },
    { t:"mc", q:"The BVN is issued through the platform operated by:", a:"NIBSS", w:["NAFDAC","FIRS","NIPOST"], e:"The Nigeria Inter-Bank Settlement System (NIBSS) operates the BVN scheme for the CBN." },
    { t:"tf", q:"A customer single BVN is the same across all the banks where the customer holds accounts.", a:"True", e:"The BVN provides one identity linked to all of a customer accounts industry-wide." },
    { t:"mc", q:"NIP, as operated by NIBSS, stands for:", a:"NIBSS Instant Payment", w:["National Investment Plan","Naira Interest Policy","New Insurance Premium"], e:"NIP enables real-time interbank electronic funds transfer in Nigeria." },
    { t:"mc", q:"USSD banking is valued mainly because it:", a:"Works on basic phones without internet access", w:["Requires a smartphone and data","Only works abroad","Needs a bank visit each time"], e:"USSD runs over the mobile network on any phone, aiding financial inclusion." },
    { t:"type", q:"The primary purpose of the BVN scheme is to reduce fraud and strengthen ______ verification in the banking system.", a:"identity", accepts:["customer","Identity"], e:"BVN links biometrics to accounts to authenticate customer identity and curb fraud." },
    { t:"mc", q:"An Automated Teller Machine (ATM) primarily enables customers to:", a:"Withdraw cash and perform self-service transactions", w:["Print the national budget","Issue banking licences","Set the policy rate"], e:"ATMs deliver cash and other self-service banking outside the branch." },
    { t:"mc", q:"Two-factor authentication improves security by requiring:", a:"Two independent forms of verification", w:["Only a username","A single password","No verification"], e:"Combining two factors, such as a card and a PIN or OTP, strengthens authentication." },
    { t:"tf", q:"A One-Time Password (OTP) is valid for a single transaction or a short period.", a:"True", e:"OTPs expire quickly and are usable once, reducing reuse fraud." },
    { t:"mc", q:"Phishing in electronic banking refers to:", a:"Tricking customers into revealing credentials via fake messages", w:["A type of treasury bill","A deposit insurance scheme","A clearing process"], e:"Phishing uses deceptive emails or sites to steal login or card details." },
    { t:"mc", q:"Point of Sale (POS) terminals are mainly used to:", a:"Accept card payments at merchant locations", w:["Issue government bonds","Print cheque books","Set exchange rates"], e:"POS devices process debit and credit card payments for goods and services." },
    { t:"mc", q:"Operational risk in a bank arises mainly from:", a:"Failed internal processes, people, systems or external events", w:["Movements in interest rates only","Borrower default only","Currency movements only"], e:"Operational risk covers losses from process, human, system or external failures." },
    { t:"mc", q:"Liquidity risk is the risk that a bank:", a:"Cannot meet its obligations as they fall due", w:["Earns too much profit","Has too many branches","Pays staff on time"], e:"Liquidity risk is the inability to fund obligations without unacceptable loss." },
    { t:"mc", q:"Market risk in banking refers to losses arising from:", a:"Changes in market prices such as interest and exchange rates", w:["A customer forgetting a PIN","A branch closing early","Staff training costs"], e:"Market risk stems from adverse movements in rates, prices and FX." },
    { t:"tf", q:"Diversification of a loan portfolio across sectors helps reduce concentration risk.", a:"True", e:"Spreading exposure limits the impact of any single sector or borrower failing." },
    { t:"type", q:"The risk that a counterparty fails to settle its side of a transaction is broadly called ______ risk.", a:"settlement", accepts:["counterparty","Settlement"], e:"Settlement or counterparty risk arises when one party does not complete a transaction." },
    { t:"mc", q:"A strong internal control environment in a bank is intended to:", a:"Safeguard assets and ensure reliable records and compliance", w:["Increase fraud opportunities","Remove all supervision","Hide losses from regulators"], e:"Internal controls protect assets, ensure accurate records and support compliance." },
    { t:"mc", q:"Which practice best protects a customer against card fraud?", a:"Keeping the PIN secret and never sharing it", w:["Writing the PIN on the card","Sharing the OTP with callers","Using the same PIN publicly"], e:"Keeping the PIN confidential is a basic and effective fraud-prevention measure." }
  ]}
];
