window.EXTRA.uni = [
  { id:"pq_uni_eng", name:"University — Use of English (GST)", emoji:"📝", cards:[
    { t:"mc", q:"Which word is the closest synonym of 'commence'?", a:"begin", w:["end","hesitate","postpone"], e:"To commence something means to begin or start it." },
    { t:"mc", q:"What is the antonym of 'benevolent'?", a:"malevolent", w:["generous","charitable","kind"], e:"Benevolent means kindly; its opposite, malevolent, means wishing harm." },
    { t:"mc", q:"Which word means the same as 'candid'?", a:"frank", w:["secretive","deceitful","vague"], e:"Candid means open and honest, that is, frank." },
    { t:"mc", q:"What is the antonym of 'scarce'?", a:"abundant", w:["rare","limited","insufficient"], e:"Scarce means in short supply, so its opposite is abundant." },
    { t:"mc", q:"Which word is a synonym of 'lucid'?", a:"clear", w:["confusing","obscure","complicated"], e:"Lucid writing is clear and easy to understand." },
    { t:"tf", q:"A synonym is a word that has a meaning similar to that of another word.", a:"True", e:"Synonyms share similar meanings, such as big and large." },
    { t:"mc", q:"What is the correct collective noun for a group of lions?", a:"a pride", w:["a flock","a herd","a swarm"], e:"A group of lions is called a pride." },
    { t:"mc", q:"What collective noun describes a large group of fish swimming together?", a:"a school", w:["a pack","a litter","a colony"], e:"Fish moving together form a school or shoal." },
    { t:"type", q:"A short, concise restatement of the main ideas of a passage is called a ______.", a:"summary", accepts:["precis","summary"], e:"A summary or precis captures the main ideas in fewer words." },
    { t:"mc", q:"What is the correct plural of 'crisis'?", a:"crises", w:["crisises","crisi","crisons"], e:"Words ending in -is, like crisis, form the plural as -es, giving crises." },
    { t:"mc", q:"What is the plural of 'datum'?", a:"data", w:["datums","datae","datas"], e:"Datum is singular and data is its Latin plural." },
    { t:"mc", q:"Which of these words is spelt correctly?", a:"accommodation", w:["acommodation","accomodation","acommadation"], e:"Accommodation has double c and double m." },
    { t:"mc", q:"A formal register is most appropriate for which of the following?", a:"a job application letter", w:["a chat with close friends", "an argument in the market", "a text message to a sibling"], e:"Formal register suits official writing such as a job application letter." },
    { t:"mc", q:"Which word means 'to make something clear or easy to understand'?", a:"elucidate", w:["obscure","complicate","mystify"], e:"To elucidate is to explain or make clear." },
    { t:"mc", q:"What is the antonym of 'optimistic'?", a:"pessimistic", w:["hopeful","cheerful","confident"], e:"An optimist expects good outcomes; a pessimist expects bad ones." },
    { t:"mc", q:"A person who studies and forecasts the weather is a ______.", a:"meteorologist", w:["geologist","astronomer","botanist"], e:"Meteorology is the study of the atmosphere and weather." },
    { t:"mc", q:"Which word is a synonym of 'meticulous'?", a:"careful", w:["careless","hasty","reckless"], e:"Meticulous means showing great care and attention to detail." },
    { t:"tf", q:"The words 'their', 'there', and 'they are' as 'they're' are homophones.", a:"True", e:"They sound alike but differ in meaning and spelling." },
    { t:"mc", q:"Which sentence is grammatically correct?", a:"I have lived here since 2010.", w:["I am living here since 2010.","I live here since 2010.","I living here since 2010."], e:"The present perfect tense is used with 'since' to show a continuing state." },
    { t:"type", q:"The antonym of 'ancient' is ______.", a:"modern", accepts:["new","contemporary","recent"], e:"Ancient means very old, so its opposite is modern." },
    { t:"mc", q:"A word that joins words, phrases, or clauses is called a ______.", a:"conjunction", w:["pronoun","adjective","preposition"], e:"Conjunctions such as and, but, and because link grammatical units." },
    { t:"mc", q:"What does 'verbose' mean?", a:"using more words than needed", w:["silent and brief","clear and concise","quick and sharp"], e:"Verbose writing is wordy and long-winded." },
    { t:"mc", q:"Which sentence is correctly punctuated?", a:"It is raining; therefore, we will stay indoors.", w:["It is raining, therefore we will stay indoors","It is raining therefore we will stay indoors.","It is raining: therefore we will, stay indoors."], e:"A semicolon links two independent clauses, and 'therefore' is set off by commas." },
    { t:"mc", q:"Which word means 'fluent and persuasive in speaking'?", a:"eloquent", w:["clumsy","tongue-tied","dull"], e:"An eloquent speaker expresses ideas clearly and persuasively." },
    { t:"mc", q:"The branch of linguistics that studies the meaning of words is called ______.", a:"semantics", w:["phonetics","syntax","morphology"], e:"Semantics deals with meaning in language." },
    { t:"mc", q:"What does a 'bibliography' contain?", a:"a list of sources used in a work", w:["the life story of the author","a list of difficult words","a table of chapter titles"], e:"A bibliography lists the books and sources consulted." },
    { t:"tf", q:"In writing a good summary, you should keep the author's main ideas while using fewer words.", a:"True", e:"Summarising retains key points but compresses the original." },
    { t:"type", q:"A word opposite in meaning to another word is called an ______.", a:"antonym", accepts:["antonym"], e:"Antonyms are words with opposite meanings, such as hot and cold." }
  ]},
  { id:"pq_uni_comm", name:"University — Communication Skills", emoji:"🗣️", cards:[
    { t:"mc", q:"Communication is best defined as the process of ______.", a:"sending and receiving messages to share meaning", w:["writing only formal letters","speaking a foreign language","reading newspapers daily"], e:"Communication is the exchange of information and meaning between people." },
    { t:"mc", q:"In the basic communication model, who originates the message?", a:"the sender", w:["the receiver","the channel","the feedback"], e:"The sender or source creates and transmits the message." },
    { t:"mc", q:"What is 'feedback' in communication?", a:"the receiver's response to the message", w:["the medium used to send the message","the noise that distorts the message","the language of the message"], e:"Feedback is the reaction the receiver sends back to the sender." },
    { t:"mc", q:"Anything that interferes with or distorts a message is called ______.", a:"noise", w:["feedback","encoding","the channel"], e:"Noise is any barrier, physical or psychological, that disrupts communication." },
    { t:"mc", q:"Which of the following is an example of non-verbal communication?", a:"body language and gestures", w:["a spoken lecture","a written letter","a telephone call"], e:"Non-verbal communication uses gestures, posture, and facial expression rather than words." },
    { t:"mc", q:"The medium through which a message travels from sender to receiver is the ______.", a:"channel", w:["sender","code","feedback"], e:"The channel is the route or medium, such as air, paper, or the internet." },
    { t:"tf", q:"Listening is an active process that requires attention and effort.", a:"True", e:"Effective listening involves concentration, interpretation, and response." },
    { t:"mc", q:"Which set lists the four basic language skills?", a:"listening, speaking, reading, writing", w:["reading, spelling, grammar, drawing","talking, singing, typing, signing","seeing, hearing, touching, writing"], e:"The four core language skills are listening, speaking, reading, and writing." },
    { t:"mc", q:"Which reading technique is used to get the general idea of a text quickly?", a:"skimming", w:["scanning","intensive reading","proofreading"], e:"Skimming means reading rapidly for the overall gist." },
    { t:"mc", q:"Which reading technique is used to locate a specific piece of information?", a:"scanning", w:["skimming","reciting","summarising"], e:"Scanning means searching a text for particular details." },
    { t:"mc", q:"Communication that takes place within one person, such as thinking, is called ______.", a:"intrapersonal communication", w:["interpersonal communication","mass communication","group communication"], e:"Intrapersonal communication occurs within an individual's own mind." },
    { t:"mc", q:"Communication between two individuals is called ______.", a:"interpersonal communication", w:["intrapersonal communication","mass communication","public communication"], e:"Interpersonal communication is a direct exchange between two people." },
    { t:"mc", q:"Communication directed at a large, scattered audience through media is called ______.", a:"mass communication", w:["intrapersonal communication","interpersonal communication","dyadic communication"], e:"Mass communication reaches large audiences via radio, television, and similar media." },
    { t:"tf", q:"Encoding is the process of converting ideas into words, symbols, or signs.", a:"True", e:"The sender encodes a message before transmitting it." },
    { t:"mc", q:"What does the receiver do when 'decoding' a message?", a:"interprets the meaning of the message", w:["sends the message back","ignores the message","adds noise to the message"], e:"Decoding is interpreting the symbols of a message to extract meaning." },
    { t:"mc", q:"SQ3R is a well-known method for ______.", a:"effective reading and study", w:["sending emails","public speaking","writing poetry"], e:"SQ3R stands for Survey, Question, Read, Recite, Review, a study technique." },
    { t:"mc", q:"Which is one of the 7 Cs of effective communication?", a:"conciseness", w:["confusion","complexity","carelessness"], e:"The 7 Cs include clarity, conciseness, correctness, completeness, and others." },
    { t:"type", q:"Communication that flows from a manager down to subordinates is called ______ communication.", a:"downward", accepts:["downward","vertical downward"], e:"Downward communication moves from higher to lower levels of an organisation." }
  ]},
  { id:"pq_uni_logic", name:"University — Logic & Philosophy", emoji:"🧠", cards:[
    { t:"mc", q:"Reasoning that moves from general premises to a specific, certain conclusion is ______.", a:"deductive reasoning", w:["inductive reasoning","analogical reasoning","abductive reasoning"], e:"Deduction draws a necessary conclusion from general premises." },
    { t:"mc", q:"Reasoning that moves from specific observations to a general conclusion is ______.", a:"inductive reasoning", w:["deductive reasoning","circular reasoning","syllogistic reasoning"], e:"Induction generalises from particular cases and gives probable conclusions." },
    { t:"mc", q:"The word 'philosophy' literally means ______.", a:"love of wisdom", w:["study of nature","knowledge of God","fear of the unknown"], e:"Philosophy comes from Greek philo (love) and sophia (wisdom)." },
    { t:"mc", q:"Which branch of philosophy studies the nature and scope of knowledge?", a:"epistemology", w:["metaphysics","ethics","aesthetics"], e:"Epistemology examines knowledge, belief, and justification." },
    { t:"mc", q:"Which branch of philosophy studies the nature of reality and existence?", a:"metaphysics", w:["epistemology","logic","ethics"], e:"Metaphysics asks what truly exists and the nature of being." },
    { t:"mc", q:"Which branch of philosophy deals with moral principles of right and wrong?", a:"ethics", w:["aesthetics","logic","epistemology"], e:"Ethics studies morality and how people ought to act." },
    { t:"mc", q:"Which branch of philosophy is concerned with beauty and art?", a:"aesthetics", w:["ethics","logic","metaphysics"], e:"Aesthetics studies beauty, taste, and artistic value." },
    { t:"mc", q:"The branch of philosophy concerned with the principles of correct reasoning is ______.", a:"logic", w:["ethics","aesthetics","metaphysics"], e:"Logic studies the structure of valid arguments and reasoning." },
    { t:"mc", q:"A statement that is either true or false is called a ______.", a:"proposition", w:["fallacy","premise","syllogism"], e:"A proposition asserts something and bears a truth value." },
    { t:"mc", q:"In an argument, the statement that is supported by reasons is the ______.", a:"conclusion", w:["premise","fallacy","analogy"], e:"The conclusion is the claim the premises are meant to support." },
    { t:"mc", q:"The statements offered as reasons or evidence in an argument are the ______.", a:"premises", w:["conclusions","fallacies","inferences"], e:"Premises provide the support for the conclusion of an argument." },
    { t:"mc", q:"A deductive argument that is valid and has all true premises is described as ______.", a:"sound", w:["invalid","cogent","false"], e:"A sound argument is valid and has true premises, guaranteeing a true conclusion." },
    { t:"mc", q:"Attacking the person making an argument rather than the argument itself is the fallacy of ______.", a:"ad hominem", w:["straw man","red herring","slippery slope"], e:"Ad hominem attacks the arguer instead of addressing the reasoning." },
    { t:"mc", q:"Misrepresenting an opponent's position so it is easier to attack is the ______ fallacy.", a:"straw man", w:["ad hominem","appeal to pity","false cause"], e:"The straw man fallacy distorts an argument to refute the distortion." },
    { t:"mc", q:"Assuming that because one event followed another the first caused the second is the ______ fallacy.", a:"false cause", w:["straw man","ad hominem","red herring"], e:"This false cause or post hoc fallacy confuses sequence with causation." },
    { t:"mc", q:"Introducing an irrelevant issue to divert attention from the real argument is a ______.", a:"red herring", w:["valid inference","sound argument","syllogism"], e:"A red herring distracts the audience from the actual point." },
    { t:"mc", q:"Arguing that a claim is true simply because most people believe it is the appeal to ______.", a:"popularity", w:["authority","pity","force"], e:"The appeal to popularity or ad populum treats wide belief as proof." },
    { t:"mc", q:"'All men are mortal; Socrates is a man; therefore Socrates is mortal' is an example of a ______.", a:"syllogism", w:["fallacy","hypothesis","metaphor"], e:"A syllogism is a deductive argument with two premises and a conclusion." },
    { t:"tf", q:"In a valid deductive argument, if all the premises are true the conclusion must also be true.", a:"True", e:"Validity means the conclusion follows necessarily from true premises." },
    { t:"mc", q:"Which ancient Greek philosopher is regarded as the founder of formal logic?", a:"Aristotle", w:["Socrates","Plato","Pythagoras"], e:"Aristotle systematised logic, especially the theory of the syllogism." }
  ]},
  { id:"pq_uni_cult", name:"University — Peoples, Culture & Citizenship", emoji:"🤝", cards:[
    { t:"mc", q:"Which is the first university established in Nigeria?", a:"University of Ibadan", w:["University of Lagos","Ahmadu Bello University","University of Nigeria, Nsukka"], e:"The University of Ibadan was founded in 1948 as the first university in Nigeria." },
    { t:"mc", q:"In what year was the University of Ibadan established?", a:"1948", w:["1960","1914","1962"], e:"It began in 1948 as University College Ibadan, affiliated to the University of London." },
    { t:"mc", q:"Which three ethnic groups are the largest in Nigeria?", a:"Hausa, Yoruba, and Igbo", w:["Tiv, Ijaw, and Nupe","Edo, Efik, and Kanuri","Fulani, Gwari, and Itsekiri"], e:"Hausa, Yoruba, and Igbo are Nigeria's three largest ethnic groups." },
    { t:"mc", q:"In what year did Nigeria gain independence from Britain?", a:"1960", w:["1957","1963","1914"], e:"Nigeria became independent on 1 October 1960." },
    { t:"mc", q:"In what year did Nigeria become a republic?", a:"1963", w:["1960","1979","1999"], e:"Nigeria became a republic in 1963, three years after independence." },
    { t:"mc", q:"The amalgamation of the Northern and Southern protectorates of Nigeria took place in ______.", a:"1914", w:["1900","1922","1960"], e:"Lord Lugard amalgamated the protectorates in 1914 to form Nigeria." },
    { t:"mc", q:"Who carried out the 1914 amalgamation of Northern and Southern Nigeria?", a:"Lord Frederick Lugard", w:["Lord Macpherson","Sir Hugh Clifford","Sir James Robertson"], e:"Lord Lugard was the colonial Governor-General who united the two protectorates." },
    { t:"mc", q:"What is the current capital city of Nigeria?", a:"Abuja", w:["Lagos","Kano","Ibadan"], e:"Abuja became Nigeria's capital in 1991, replacing Lagos." },
    { t:"mc", q:"How many states make up the Nigerian federation?", a:"36", w:["30","19","774"], e:"Nigeria has 36 states plus the Federal Capital Territory." },
    { t:"mc", q:"How many local government areas does Nigeria have?", a:"774", w:["360","109","36"], e:"There are 774 local government areas in Nigeria." },
    { t:"mc", q:"Citizenship is best defined as ______.", a:"legal membership of a state with rights and duties", w:["the place where one was born only","being employed by the government","owning land in a country"], e:"Citizenship confers legal status, rights, and responsibilities within a state." },
    { t:"mc", q:"A foreigner who lives long-term in Nigeria and meets the legal requirements may gain citizenship by ______.", a:"naturalization", w:["birth","descent","inheritance"], e:"Naturalization grants citizenship to qualified foreigners after meeting residency conditions." },
    { t:"tf", q:"Paying taxes is a civic responsibility expected of citizens.", a:"True", e:"Citizens have duties such as paying taxes and obeying the law." },
    { t:"mc", q:"What is the traditional title of a Yoruba paramount ruler?", a:"Oba", w:["Emir","Obi","Etsu"], e:"Among the Yoruba, a traditional king is called an Oba." },
    { t:"mc", q:"Among the Hausa and Fulani, the traditional ruler is known as the ______.", a:"Emir", w:["Oba","Obi","Olu"], e:"The Emir is the traditional Islamic ruler in Hausa-Fulani society." },
    { t:"mc", q:"What is the official currency of Nigeria?", a:"the Naira", w:["the Cedi","the Shilling","the Franc"], e:"Nigeria's currency is the Naira, divided into kobo." },
    { t:"mc", q:"Which of the following belongs to material culture?", a:"tools and buildings", w:["beliefs","values","language"], e:"Material culture consists of physical objects, while beliefs and values are non-material." },
    { t:"mc", q:"Which arm of government is responsible for making laws?", a:"the legislature", w:["the executive","the judiciary","the civil service"], e:"The legislature makes laws, the executive implements them, and the judiciary interprets them." }
  ]},
  { id:"pq_uni_ict", name:"University — ICT & Entrepreneurship", emoji:"💻", cards:[
    { t:"mc", q:"What does the abbreviation CPU stand for?", a:"Central Processing Unit", w:["Computer Power Unit","Central Programming Unit","Control Processing Utility"], e:"The CPU, or Central Processing Unit, executes instructions in a computer." },
    { t:"mc", q:"Which component is often called the brain of the computer?", a:"the CPU", w:["the monitor","the keyboard","the printer"], e:"The CPU processes data and controls the computer, acting as its brain." },
    { t:"mc", q:"What does RAM stand for?", a:"Random Access Memory", w:["Read And Memorise","Rapid Active Memory","Remote Access Module"], e:"RAM is the computer's main working memory for active tasks." },
    { t:"mc", q:"RAM is described as volatile memory because it ______.", a:"loses its contents when power is switched off", w:["can never be erased","stores data permanently","is only used for printing"], e:"Volatile memory like RAM needs power to retain its data." },
    { t:"mc", q:"Which of the following is an input device?", a:"keyboard", w:["monitor","printer","speaker"], e:"A keyboard sends data into the computer, making it an input device." },
    { t:"mc", q:"Which of the following is an output device?", a:"printer", w:["mouse","scanner","keyboard"], e:"A printer produces output from the computer onto paper." },
    { t:"mc", q:"Software that manages a computer's hardware and resources is the ______.", a:"operating system", w:["web browser","antivirus","spreadsheet"], e:"The operating system controls hardware and provides a platform for applications." },
    { t:"mc", q:"Which of the following is an example of an operating system?", a:"Windows", w:["Microsoft Word","Microsoft Excel","Google Chrome"], e:"Windows is an operating system, while the others are application programs." },
    { t:"mc", q:"What does the abbreviation WWW stand for?", a:"World Wide Web", w:["World Wireless Web","Wide World Website","Web World Wireless"], e:"The World Wide Web is the system of linked documents accessed over the internet." },
    { t:"mc", q:"How many bits make up one byte?", a:"8", w:["4","16","2"], e:"One byte equals eight bits." },
    { t:"type", q:"ICT stands for Information and ______ Technology.", a:"Communication", accepts:["Communications"], e:"ICT means Information and Communication Technology." },
    { t:"mc", q:"A program written to harm a computer or spread without permission is called a ______.", a:"virus", w:["browser","compiler","driver"], e:"A computer virus is malicious software that damages or disrupts systems." },
    { t:"mc", q:"An entrepreneur is best described as a person who ______.", a:"starts and runs a business while bearing the risks", w:["only works for a salary","lends money to banks","collects taxes for government"], e:"An entrepreneur organises resources and takes risks to run a business." },
    { t:"mc", q:"The money or resources used to start and run a business is called ______.", a:"capital", w:["profit","interest","dividend"], e:"Capital is the funding and resources invested in a business." },
    { t:"mc", q:"Profit is calculated as total revenue minus total ______.", a:"costs", w:["capital","assets","sales"], e:"Profit is what remains after subtracting all costs from revenue." },
    { t:"tf", q:"Entrepreneurship can help reduce unemployment by creating new jobs.", a:"True", e:"New businesses generate employment and contribute to economic growth." }
  ]}
];
window.EXTRA = window.EXTRA || {};
window.EXTRA.voc = [
  { id:"voc_carp", name:"Carpentry & Woodwork", emoji:"🪚", cards:[
    { t:"mc", q:"Which hand tool is used to make a surface of timber smooth and flat by shaving off thin layers of wood?", a:"Plane", w:["Try square","Tenon saw","Mallet"], e:"A plane removes thin shavings to flatten and smooth a timber surface." },
    { t:"mc", q:"What is a try square mainly used for in carpentry?", a:"Marking and checking right angles (90 degrees)", w:["Cutting curves in wood","Tightening screws","Smoothing rough timber"], e:"A try square checks and marks 90-degree angles between edges." },
    { t:"mc", q:"A chisel is best driven into wood using which tool to avoid damaging the handle?", a:"A wooden mallet", w:["A steel claw hammer","A pair of pliers","A screwdriver"], e:"A wooden mallet protects the chisel handle, while a steel hammer can crack it." },
    { t:"mc", q:"Which saw is designed for fine, straight cuts such as cutting joints?", a:"Tenon saw", w:["Hacksaw","Bow saw","Coping saw"], e:"A tenon saw has fine teeth and a stiff back for accurate straight cuts in joinery." },
    { t:"mc", q:"Which of these is a strong wood joint commonly used to connect a rail to a leg in furniture?", a:"Mortise and tenon joint", w:["Soldered joint","Compression joint","Butt weld"], e:"The mortise and tenon joint is a classic strong woodworking joint for frames and furniture." },
    { t:"tf", q:"You should always cut wood away from your body and keep your hands behind the cutting edge of a chisel.", a:"True", e:"Cutting away from the body keeps hands clear of the blade if it slips." },
    { t:"tf", q:"Hardwoods like mahogany generally come from broad-leaved trees, while softwoods come from conifers such as pine.", a:"True", e:"Hardwood comes from broad-leaved (deciduous) trees and softwood from coniferous trees." },
    { t:"type", q:"Wearing safety ______ protects the eyes from flying wood chips and sawdust when sawing or chiselling.", a:"goggles", accepts:["glasses","eye goggles"], e:"Goggles shield the eyes from chips and dust during cutting." },
    { t:"mc", q:"Why should timber be properly seasoned (dried) before use?", a:"To reduce shrinking, warping and cracking after the work is built", w:["To make it heavier","To make it conduct electricity","To make it burn faster"], e:"Seasoning lowers moisture so the wood is stable and does not warp later." },
    { t:"type", q:"A carpenter uses a tape measure or rule to measure and a ______ to mark a straight cutting line on timber.", a:"pencil", accepts:["marking knife","pencil or knife"], e:"A pencil (or marking knife) is used to mark cutting lines accurately." }
  ]},
  { id:"voc_hair", name:"Hairdressing & Beauty", emoji:"💇", cards:[
    { t:"mc", q:"Why must combs, scissors and clippers be cleaned and disinfected between clients?", a:"To prevent the spread of infections and scalp conditions", w:["To make the tools heavier","To change the hair colour","To make hair grow faster"], e:"Sterilising tools between clients stops germs, lice and scalp infections from spreading." },
    { t:"mc", q:"What should a barber do before starting work on a new client to protect against germs?", a:"Wash hands and use clean, disinfected tools", w:["Use the same uncleaned blade all day","Skip washing to save time","Share towels between clients"], e:"Clean hands and disinfected tools are basic hygiene that protect both client and barber." },
    { t:"tf", q:"A patch (skin) test should be done before using a chemical hair relaxer or dye to check for allergic reaction.", a:"True", e:"A patch test warns of allergy or irritation before the chemical is applied fully." },
    { t:"mc", q:"Disposable razor blades used for shaving should be:", a:"Used once and then safely discarded", w:["Reused on many clients without cleaning","Washed with plain water and reused for days","Kept loose in a pocket"], e:"Single-use blades are discarded after one client to avoid spreading blood-borne germs." },
    { t:"tf", q:"Hair conditioner is mainly used to clean dirt and oil out of the hair, the same job as shampoo.", a:"False", e:"Shampoo cleans the hair, while conditioner smooths and moisturises it." },
    { t:"mc", q:"Which item is personal protective equipment that keeps relaxer or dye chemicals off the stylist's skin?", a:"Gloves", w:["A wide-tooth comb","A blow dryer","A hand mirror"], e:"Gloves protect the stylist's hands from chemical burns and irritation." },
    { t:"mc", q:"Good customer care in a salon includes:", a:"Greeting clients politely and listening to what style they want", w:["Ignoring the client and rushing the job","Talking only on the phone","Charging a different price than agreed"], e:"Polite greetings and listening build trust and bring repeat customers." },
    { t:"type", q:"The clear protective ______ tied around a client's neck and shoulders catches cut hair and keeps clothes clean.", a:"cape", accepts:["gown","barber cape"], e:"A cape (or gown) keeps loose hair off the client's clothing." },
    { t:"tf", q:"Relaxer chemicals should be kept away from the eyes, and any splash should be rinsed out with plenty of water immediately.", a:"True", e:"Relaxers are caustic, so eye splashes must be flushed with water at once." },
    { t:"mc", q:"Which simple action helps prevent skin infections when piercing or working very close to the skin?", a:"Sterilise tools and clean the skin first", w:["Use a rusty needle","Skip cleaning to save time","Reuse a dirty blade"], e:"Sterile tools and clean skin reduce the risk of infection." }
  ]},
  { id:"voc_mech", name:"Auto Mechanic", emoji:"🔧", cards:[
    { t:"mc", q:"What is the main job of engine oil in a motor vehicle?", a:"To lubricate moving parts and reduce friction and wear", w:["To cool the cabin air","To clean the windscreen","To power the radio"], e:"Engine oil lubricates and reduces friction between moving engine parts." },
    { t:"mc", q:"Which fluid keeps the engine from overheating by carrying heat away to the radiator?", a:"Coolant (radiator water/antifreeze)", w:["Brake fluid","Petrol","Engine oil only"], e:"Coolant circulates through the engine and radiator to remove heat." },
    { t:"tf", q:"You should never open a hot radiator cap on a running or recently driven engine because pressurised hot water can spray out and burn you.", a:"True", e:"A hot pressurised cooling system can release scalding steam and coolant." },
    { t:"mc", q:"Which tool is used to loosen and tighten the nuts and bolts on a wheel?", a:"Wheel spanner / lug wrench", w:["Screwdriver","Pliers","Hacksaw"], e:"A wheel spanner (lug wrench) fits the wheel nuts to remove or fit a wheel." },
    { t:"mc", q:"Before working underneath a vehicle raised on a jack, what should you also place for safety?", a:"Axle stands (jack stands)", w:["A plastic bucket","A pile of bricks balanced loosely","Nothing, the jack is enough"], e:"Axle stands hold the vehicle safely if the jack fails or slips." },
    { t:"mc", q:"What does a car battery mainly provide?", a:"Electrical power to start the engine and run electrical parts", w:["Fuel for the engine","Cooling for the radiator","Air for the tyres"], e:"The battery supplies electricity to start the engine and power lights and electronics." },
    { t:"tf", q:"Worn or under-inflated tyres are a safety risk because they reduce grip and can cause loss of control.", a:"True", e:"Bad tyres reduce traction and braking, raising the risk of accidents." },
    { t:"type", q:"During a routine service, the air ______ is checked or replaced so the engine gets clean air for combustion.", a:"filter", accepts:["air filter","filter element"], e:"The air filter removes dust so only clean air enters the engine." },
    { t:"mc", q:"Which fluid is used in the hydraulic system that makes the brakes work?", a:"Brake fluid", w:["Engine oil","Coolant","Petrol"], e:"Brake fluid transmits pedal pressure through the hydraulic brake system." },
    { t:"tf", q:"It is safe to smoke or use an open flame while refuelling or near petrol vapour.", a:"False", e:"Petrol vapour is highly flammable, so flames and sparks must be kept away." }
  ]},
  { id:"voc_tailor", name:"Tailoring & Fashion", emoji:"🧵", cards:[
    { t:"mc", q:"On a sewing machine, what is the job of the bobbin?", a:"It holds the lower thread that joins with the top thread to form a stitch", w:["It cuts the fabric","It irons the seam","It measures the body"], e:"The bobbin supplies the lower thread that locks with the needle thread." },
    { t:"mc", q:"Which tool is used to take accurate body measurements for a garment?", a:"Tape measure", w:["Try square","Spirit level","Spanner"], e:"A flexible tape measure follows body curves to give accurate measurements." },
    { t:"mc", q:"A paper ______ is the template a tailor uses to cut fabric pieces to the correct shape and size.", a:"pattern", w:["bobbin","seam","selvedge"], e:"A pattern is the template that guides cutting of each fabric piece." },
    { t:"tf", q:"You should always leave extra fabric called a seam allowance beyond the stitching line when cutting out a garment.", a:"True", e:"Seam allowance gives room to join pieces and adjust the fit." },
    { t:"mc", q:"Which fabric is a natural fibre made from the cotton plant and is cool to wear?", a:"Cotton", w:["Polyester","Nylon","Acrylic"], e:"Cotton is a breathable natural fibre from the cotton plant." },
    { t:"mc", q:"What is a hem in a finished garment?", a:"The folded and stitched edge at the bottom of a garment or sleeve", w:["The shoulder seam","The collar lining","The waistband button"], e:"A hem is the turned-under, stitched edge that neatens a raw bottom edge." },
    { t:"tf", q:"A tacking (basting) stitch is a temporary stitch used to hold fabric in place before final sewing.", a:"True", e:"Tacking holds pieces together temporarily and is removed after final stitching." },
    { t:"type", q:"Before sewing, a tailor often uses ______ pins to hold two pieces of fabric together temporarily.", a:"sewing", accepts:["dressmaking","straight"], e:"Sewing pins hold layers together until they are stitched." },
    { t:"mc", q:"Why should you press (iron) seams as you sew a garment?", a:"To make seams flat and the finished garment neat and professional", w:["To shrink the buttons","To remove the thread","To change the fabric colour"], e:"Pressing flattens seams for a clean, well-finished look." },
    { t:"mc", q:"On a sewing machine, what is the main purpose of the presser foot?", a:"To hold the fabric firmly against the feed dogs as it is stitched", w:["To wind the bobbin","To cut the thread tail","To oil the machine"], e:"The presser foot keeps fabric flat and moving evenly under the needle." }
  ]},
  { id:"voc_elec", name:"Electrical Installation", emoji:"💡", cards:[
    { t:"mc", q:"In modern wiring used in Nigeria, what colour is the earth (ground) wire?", a:"Green-and-yellow stripes", w:["Plain red","Plain black","Plain white"], e:"The protective earth conductor is identified by green-and-yellow striping." },
    { t:"mc", q:"What is the main purpose of a fuse or circuit breaker in a circuit?", a:"To break the circuit if too much current flows, preventing fire", w:["To increase the voltage","To store electricity","To make lights brighter"], e:"A fuse or breaker cuts the supply on overload, protecting against fire." },
    { t:"tf", q:"Earthing (grounding) metal appliances helps protect a person from electric shock if a fault occurs.", a:"True", e:"Earthing gives fault current a safe path and trips protection, reducing shock risk." },
    { t:"mc", q:"Before working on a circuit, the safest first step is to:", a:"Switch off the supply and confirm it is dead", w:["Work quickly while it is live","Wear sandals and continue","Pour water on the wires"], e:"Isolating and proving the circuit dead prevents electric shock." },
    { t:"mc", q:"Which conductor in a UK/Nigeria-style colour code is the live (line) wire?", a:"Brown", w:["Blue","Green-and-yellow","Grey"], e:"In the modern code brown is line (live) and blue is neutral." },
    { t:"tf", q:"You should never touch electrical switches or appliances with wet hands or while standing in water.", a:"True", e:"Water conducts electricity, so wet contact greatly increases shock risk." },
    { t:"mc", q:"What does a thicker copper cable allow compared with a thin one?", a:"It can safely carry more current", w:["It carries less current","It blocks all current","It only works with batteries"], e:"A larger cross-section conductor safely carries a higher current." },
    { t:"type", q:"The unit used to measure electrical current is the ______.", a:"ampere", accepts:["amp","amps","amperes"], e:"Current is measured in amperes (amps)." },
    { t:"mc", q:"Why are most electrical cables covered in plastic or rubber?", a:"The covering is an insulator that prevents shock and short circuits", w:["To make them conduct better","To add weight","For decoration only"], e:"Insulation stops accidental contact and short circuits between conductors." },
    { t:"tf", q:"Overloading one socket with many high-power appliances through adaptors is safe and recommended.", a:"False", e:"Overloading a socket can overheat the wiring and cause a fire." }
  ]},
  { id:"voc_cater", name:"Catering & Baking", emoji:"🍰", cards:[
    { t:"mc", q:"The food 'danger zone' where bacteria multiply fastest is roughly which temperature range?", a:"Between 5 and 60 degrees Celsius", w:["Below 0 degrees Celsius","Above 100 degrees Celsius","Exactly at freezing only"], e:"Bacteria grow rapidly between about 5 and 60 degrees Celsius." },
    { t:"mc", q:"What is the single most important hygiene habit before handling food?", a:"Washing hands thoroughly with soap and water", w:["Wearing sunglasses","Turning off the lights","Counting the plates"], e:"Handwashing removes germs that can contaminate food." },
    { t:"mc", q:"In the classic pound cake formula, flour, sugar, fat and eggs are used in what ratio?", a:"Equal parts (1:1:1:1)", w:["3 parts flour to 1 of everything","No fat at all","10 parts sugar to 1 flour"], e:"A traditional pound cake uses equal weights of flour, sugar, butter and eggs." },
    { t:"tf", q:"Raw meat should be kept separate from cooked or ready-to-eat food to avoid cross-contamination.", a:"True", e:"Separating raw and cooked food stops germs spreading between them." },
    { t:"mc", q:"What does the leavening agent baking powder do in a cake?", a:"It releases gas that makes the cake rise and become light", w:["It sweetens the cake","It colours the cake","It cools the oven"], e:"Baking powder produces gas bubbles that make the batter rise." },
    { t:"mc", q:"The HACCP food-safety system is mainly used to:", a:"Identify and control hazards at key points in food preparation", w:["Decorate cakes","Set the price of food","Choose the menu colours"], e:"HACCP finds and controls biological, chemical and physical hazards in food handling." },
    { t:"tf", q:"Cooked food left at room temperature for many hours is safe to eat without reheating.", a:"False", e:"Food left in the danger zone too long can grow harmful bacteria." },
    { t:"type", q:"When baking, the creaming method beats together butter (fat) and ______ until light and fluffy to trap air.", a:"sugar", accepts:["sugar (granulated)"], e:"Creaming butter and sugar traps air that helps the cake rise." },
    { t:"mc", q:"Why should a baker preheat the oven before putting the cake in?", a:"So the cake bakes evenly at the correct temperature from the start", w:["To save electricity","To make the cake heavier","To change the flour"], e:"A preheated oven ensures even rising and proper baking." },
    { t:"tf", q:"Keeping long hair tied back and wearing a clean apron are good kitchen hygiene practices.", a:"True", e:"Tied hair and clean clothing help keep hair and dirt out of food." }
  ]},
  { id:"voc_weld", name:"Welding & Fabrication", emoji:"🔥", cards:[
    { t:"mc", q:"Why must a welder wear a welding helmet with a dark filter lens?", a:"To protect the eyes from intense light and ultraviolet radiation (arc eye)", w:["To keep the head warm","To hear the machine better","To smell the metal"], e:"The dark filter shields eyes from harmful UV, infrared and bright light that cause arc eye." },
    { t:"mc", q:"Which welding process uses an electric arc and a coated electrode (a 'stick')?", a:"Arc welding (MMA / stick welding)", w:["Riveting","Soldering with a flame only","Bolting"], e:"Stick (MMA) arc welding melts metal using an electric arc and a consumable electrode." },
    { t:"tf", q:"Welding fumes can be harmful, so welding should be done in a well-ventilated area.", a:"True", e:"Good ventilation removes toxic fumes and gases produced during welding." },
    { t:"mc", q:"What protective clothing helps prevent burns from sparks and hot metal during welding?", a:"Leather gloves and a flame-resistant apron", w:["Cotton singlet and shorts","Plastic raincoat","Open sandals"], e:"Leather gloves and flame-resistant clothing resist sparks and heat." },
    { t:"mc", q:"Looking at a welding arc with the naked eye can cause a painful condition known as:", a:"Arc eye (welder's flash)", w:["Common cold","Toothache","Hearing loss"], e:"The arc's UV light burns the eye surface, causing arc eye (welder's flash)." },
    { t:"tf", q:"Welding near petrol, gas cylinders or other flammable materials is dangerous and should be avoided.", a:"True", e:"Sparks and heat can ignite nearby flammable materials and cause fire or explosion." },
    { t:"mc", q:"Which metal is an alloy mainly of iron and carbon, widely welded in fabrication?", a:"Steel", w:["Pure gold","Glass","Rubber"], e:"Steel is an iron-carbon alloy and the most commonly welded structural metal." },
    { t:"type", q:"A fire ______ should be kept nearby in the workshop in case sparks start a fire.", a:"extinguisher", accepts:["extinguisher or bucket of sand","fire extinguisher"], e:"A fire extinguisher lets you put out small fires quickly." },
    { t:"mc", q:"Gas welding commonly uses oxygen combined with which fuel gas to produce a hot flame?", a:"Acetylene", w:["Carbon dioxide","Nitrogen","Helium"], e:"Oxy-acetylene welding burns acetylene with oxygen for a very hot flame." },
    { t:"tf", q:"Hot metal looks the same as cold metal after welding, so you can grab a finished weld with bare hands immediately.", a:"False", e:"Recently welded metal stays dangerously hot and can cause serious burns." }
  ]},
  { id:"voc_plumb", name:"Plumbing", emoji:"🚰", cards:[
    { t:"mc", q:"What is the main use of PVC pipe in plumbing?", a:"Carrying water in cold-water supply and drainage lines", w:["Conducting electricity","Welding steel","Storing fuel"], e:"PVC is a common plastic pipe used for cold water supply and waste drainage." },
    { t:"mc", q:"Which tool is used to grip and turn pipes and large round fittings?", a:"Pipe wrench", w:["Tenon saw","Try square","Soldering iron"], e:"A pipe wrench grips round pipe so it can be turned and tightened." },
    { t:"mc", q:"What is the job of a tap (faucet) valve in a water system?", a:"To control or stop the flow of water", w:["To heat the water","To measure the pipe length","To colour the water"], e:"A tap or valve opens and closes to control water flow." },
    { t:"tf", q:"Plumbers wrap thread tape (PTFE) around threaded joints to help prevent leaks.", a:"True", e:"Thread tape seals the threads so the joint does not leak." },
    { t:"mc", q:"A common cause of a dripping tap that a plumber repairs is a worn:", a:"Washer or seal", w:["Light bulb","Door hinge","Car tyre"], e:"A worn washer or seal lets water pass, causing the tap to drip." },
    { t:"mc", q:"What does a P-trap (the U-shaped bend) under a sink do?", a:"Holds water that blocks bad sewer smells from rising into the room", w:["Heats the water","Filters drinking water","Generates electricity"], e:"The water sitting in the trap forms a seal against drain gases." },
    { t:"tf", q:"Before repairing a leaking pipe, you should first shut off the water supply to that line.", a:"True", e:"Turning off the supply stops water flow so the repair can be done safely." },
    { t:"type", q:"Water flows downhill, so drainage and waste pipes are laid at a slight ______ (slope) to drain properly.", a:"gradient", accepts:["slope","fall","incline"], e:"A slight downward gradient lets gravity drain waste water away." },
    { t:"mc", q:"Which safety gear protects a plumber's hands from sharp pipe edges and dirty water?", a:"Work gloves", w:["A welding helmet","Earmuffs only","A chef's hat"], e:"Work gloves protect hands from cuts and contaminated water." },
    { t:"tf", q:"Drinking-water pipes and sewage (waste) pipes should be kept separate to avoid contaminating clean water.", a:"True", e:"Mixing clean and waste lines can contaminate drinking water and cause illness." }
  ]},
  { id:"voc_biz", name:"Run Your Trade as a Business", emoji:"💰", cards:[
    { t:"mc", q:"To set a price that makes a profit, you must first know your:", a:"Total cost of materials and labour", w:["Favourite colour","Neighbour's age","The day of the week"], e:"Knowing your costs lets you price above them and earn a profit." },
    { t:"mc", q:"What does 'profit' mean in a small trade business?", a:"The money left after subtracting costs from the money earned", w:["The total money collected before costs","The amount of materials bought","The number of customers"], e:"Profit is income (sales) minus all the costs of doing the work." },
    { t:"tf", q:"Keeping written records of money coming in and going out helps you know if your business is making a profit.", a:"True", e:"Records show income and expenses so you can track profit or loss." },
    { t:"mc", q:"Why is it wise to separate your business money from your personal money?", a:"So you can see the true performance of the business and not spend its capital", w:["Because banks forbid personal money","So you never have to pay suppliers","To make the business pay no costs"], e:"Separating funds keeps business capital intact and shows real performance." },
    { t:"mc", q:"A simple, low-cost way for an artisan to get more customers is to:", a:"Do good work and ask happy customers to refer others (word of mouth)", w:["Hide the workshop location","Be rude to customers","Refuse to give prices"], e:"Quality work and referrals spread your reputation cheaply." },
    { t:"tf", q:"Saving part of your earnings regularly helps you buy better tools and survive slow periods.", a:"True", e:"Savings provide capital for growth and a cushion when work is slow." },
    { t:"mc", q:"If a job will use 2000 naira of materials, a fair price to the customer should be:", a:"More than 2000 naira, to also cover your labour and profit", w:["Exactly 2000 naira","Less than 2000 naira","Zero, work for free"], e:"Price must cover materials plus labour and profit, or you lose money." },
    { t:"type", q:"A written estimate of what a job will cost, given to a customer before work starts, is called a ______.", a:"quote", accepts:["quotation","estimate"], e:"A quote tells the customer the expected cost before work begins." },
    { t:"mc", q:"Good customer service that brings repeat business includes:", a:"Finishing on time and keeping your promises", w:["Always arriving very late","Ignoring complaints","Changing the price after agreeing"], e:"Reliability and honesty build trust and repeat customers." },
    { t:"tf", q:"Buying materials in larger quantities at a wholesale price can lower the cost per item and increase profit.", a:"True", e:"Buying in bulk often reduces the unit cost, widening your profit margin." }
  ]}
];
