window.EXTRA.voc2 = [
  { id:"voc_phone", name:"Phone & Electronics Repair", emoji:"📱", cards:[
    { t:"mc", q:"What does ESD stand for, the hidden hazard that can silently damage a phone motherboard?", a:"Electrostatic discharge", w:["Electronic system default","Excess static drain","Electrical short detection"], e:"ESD is the sudden flow of static electricity that can permanently damage sensitive chips." },
    { t:"mc", q:"Which item should a technician wear to safely ground their body and prevent static damage to components?", a:"Anti-static wrist strap", w:["Rubber kitchen gloves","A woollen jumper","A magnetic bracelet"], e:"An anti-static wrist strap bleeds body static to ground, protecting delicate ICs." },
    { t:"mc", q:"What is the very first step before opening a phone to work on its board?", a:"Power off the phone and disconnect the battery", w:["Increase the screen brightness", "Charge it to 100 percent first","Connect it to Wi-Fi"], e:"Disconnecting the battery removes power, reducing short-circuit and ESD risk." },
    { t:"mc", q:"Which tool is used to safely lift a phone screen during disassembly?", a:"Suction cup", w:["Claw hammer","Wood chisel","Paint roller"], e:"A suction cup grips the glass so the screen can be lifted evenly without cracking it." },
    { t:"mc", q:"What is a multimeter mainly used for in phone repair?", a:"Measuring voltage and finding short circuits", w:["Heating solder joints","Cutting flex cables","Polishing the screen"], e:"A multimeter checks voltage, continuity and shorts to diagnose board faults." },
    { t:"tf", q:"Components and IC chips should be stored in anti-static bags or conductive foam rather than loose in plastic boxes.", a:"True", e:"Anti-static packaging prevents static buildup that can damage stored chips." },
    { t:"tf", q:"You should hold a phone motherboard by its edges and avoid touching the IC pins and solder pads with bare fingers.", a:"True", e:"Skin carries static and oils, so handling boards by the edges protects the components." },
    { t:"type", q:"A temperature-controlled ______ iron is used to melt solder when reattaching a charging port or component.", a:"soldering", accepts:["solder"], e:"A soldering iron melts solder to join components to the board." },
    { t:"type", q:"Isopropyl alcohol (______) is commonly used to clean flux, dust and corrosion from circuit boards.", a:"IPA", accepts:["alcohol","isopropyl"], e:"IPA evaporates cleanly and removes flux residue without leaving moisture." },
    { t:"mc", q:"For a small repair business, why is it wise to test a phone and quote the customer before starting work?", a:"It sets clear expectations and protects you from disputes over price and faults", w:["It lets you keep the customer's SIM card","It avoids ever needing tools","It guarantees the part is free"], e:"Diagnosing and quoting first builds trust and prevents arguments about cost or pre-existing damage." }
  ]},
  { id:"voc_solar", name:"Solar & Inverter Installation", emoji:"🔆", cards:[
    { t:"mc", q:"What is the main job of a solar charge controller in a battery system?", a:"To regulate charging and protect the battery from overcharging", w:["To convert DC to AC for appliances","To cool the solar panels","To increase panel wattage"], e:"The charge controller manages current from panels to batteries, preventing overcharge damage." },
    { t:"mc", q:"What does an inverter do in a solar power system?", a:"Converts DC from the battery into AC for household appliances", w:["Converts AC into sunlight","Stores energy chemically","Cleans the solar panels"], e:"Most home appliances need AC, so the inverter changes battery DC into AC." },
    { t:"mc", q:"Connecting batteries in series (positive to negative) does what?", a:"Increases the total voltage", w:["Increases the amp-hour capacity only","Reduces the voltage to zero","Cools the batteries"], e:"Series wiring adds voltages together while capacity stays the same." },
    { t:"mc", q:"Connecting batteries in parallel (positive to positive) does what?", a:"Increases the total capacity (amp-hours) at the same voltage", w:["Increases the voltage","Turns DC into AC","Stops them charging"], e:"Parallel wiring adds capacity while keeping the same voltage." },
    { t:"mc", q:"Which type of charge controller is generally more efficient and harvests more energy from the panels?", a:"MPPT", w:["PWM","ELCB","RCD"], e:"MPPT controllers track the panel's maximum power point, extracting more energy than PWM types." },
    { t:"tf", q:"A fuse or circuit breaker should be fitted between the battery and the rest of the system to protect against short circuits and overcurrent.", a:"True", e:"Fuses and breakers cut the current during a fault, preventing fire and equipment damage." },
    { t:"tf", q:"Solar panels still produce dangerous voltage in daylight even when not connected to a battery, so they should be covered or handled with care during wiring.", a:"True", e:"Panels generate voltage whenever light hits them, so they remain a live electrical hazard." },
    { t:"type", q:"The solar array should be properly ______ (connected to earth) to protect against electric shock and lightning surges.", a:"earthed", accepts:["grounded","earth","grounding"], e:"Earthing gives fault current a safe path and reduces shock and surge risk." },
    { t:"mc", q:"Basic system sizing starts by first estimating which of these?", a:"The daily energy demand (watt-hours) of the appliances to be powered", w:["The colour of the roof","The brand of the cables","The price of fuel"], e:"You add up appliance watt-hours to size panels, battery and inverter correctly." },
    { t:"mc", q:"Why should an installer match the inverter's rated capacity to the customer's load?", a:"An undersized inverter will overload and an oversized one wastes money", w:["Bigger is always better regardless of cost","Capacity has no effect on performance","It changes the sunlight available"], e:"Correct sizing keeps the system reliable and cost-effective for the customer." }
  ]},
  { id:"voc_makeup", name:"Makeup Artistry", emoji:"💄", cards:[
    { t:"mc", q:"Why should a makeup artist use a clean spatula to scoop product from a jar instead of fingers?", a:"To avoid contaminating the product with bacteria", w:["To make the product last shorter","To change the product colour","To warm the product up"], e:"A spatula keeps fingers and germs out of shared products, protecting every client." },
    { t:"mc", q:"What is the hygienic way to apply mascara or lip product to multiple clients?", a:"Use a fresh disposable wand or applicator for each client", w:["Use the same wand and wipe it on tissue","Blow on the wand to clean it","Share one wand all day"], e:"Disposable wands prevent eye and lip infections from passing between clients." },
    { t:"mc", q:"Which skin type tends to produce excess sebum and look shiny, often needing a mattifying primer?", a:"Oily skin", w:["Dry skin","Dehydrated skin","Sensitive skin"], e:"Oily skin overproduces sebum, so mattifying products help control shine." },
    { t:"mc", q:"Before applying foundation, the skin should first be cleansed and then have which product applied?", a:"Moisturiser (and primer)", w:["Nail polish","Hair gel","Shoe cream"], e:"Cleansing then moisturising and priming creates a smooth, hydrated base for foundation." },
    { t:"mc", q:"Why should makeup brushes be washed regularly with brush cleaner or mild soap?", a:"To remove bacteria, old product and oils that cause breakouts", w:["To make the bristles fall out","To change the brush shape permanently","To make them heavier"], e:"Clean brushes prevent bacteria buildup that can cause skin infections and breakouts." },
    { t:"tf", q:"A patch test can help check whether a client may react to a product before it is applied to the whole face.", a:"True", e:"Testing a small area first warns of allergy or irritation before full application." },
    { t:"tf", q:"It is good practice to wash or sanitise your hands before starting on each client.", a:"True", e:"Clean hands are the first step in protecting the client from germs." },
    { t:"type", q:"To match foundation correctly, the artist tests shades along the client's jaw or ______ line in good natural light.", a:"jawline", accepts:["jaw","neck"], e:"Testing on the jaw or neck in daylight gives the truest colour match." },
    { t:"type", q:"A ______ is used to blend foundation and concealer for a smooth, airbrushed finish.", a:"sponge", accepts:["beauty sponge","blender","beauty blender"], e:"A damp makeup sponge presses and blends product for an even finish." },
    { t:"mc", q:"For client care in a makeup business, why is it important to confirm the look and occasion before starting?", a:"It ensures the result meets the client's expectations and builds repeat business", w:["It lets you skip cleaning your tools","It means you can use expired products","It removes the need for good lighting"], e:"Understanding the client's needs first leads to satisfaction, referrals and repeat bookings." }
  ]},
  { id:"voc_photo", name:"Photography & Videography", emoji:"📷", cards:[
    { t:"mc", q:"The three settings of the exposure triangle are aperture, ISO and which third one?", a:"Shutter speed", w:["White balance","Megapixels","Zoom ratio"], e:"Aperture, ISO and shutter speed together control how bright or dark an image is." },
    { t:"mc", q:"What does a wider aperture (smaller f-number like f/1.8) do?", a:"Lets in more light and gives a shallow depth of field (blurred background)", w:["Lets in less light and freezes motion","Increases the file size only","Changes the colour temperature"], e:"A wide aperture lets in more light and blurs the background behind the subject." },
    { t:"mc", q:"Raising the ISO value too high tends to cause what in a photo?", a:"More grain or noise", w:["Sharper focus everywhere","A wider lens angle","Faster autofocus"], e:"High ISO boosts sensor sensitivity but adds visible grain or noise to the image." },
    { t:"mc", q:"The rule of thirds suggests placing your main subject where?", a:"Along the lines or at the intersections of a 3x3 grid", w:["Always dead centre of the frame","In the darkest corner","Out of focus at the edge"], e:"Placing subjects on the grid lines or crossings creates a more balanced, pleasing composition." },
    { t:"mc", q:"What does white balance control in an image?", a:"How accurate the colours look under different light (warm or cool)", w:["The shutter speed","The lens focal length","The battery life"], e:"White balance corrects colour casts so whites look white under any light source." },
    { t:"mc", q:"To freeze a fast-moving subject sharply, you should use a:", a:"Fast shutter speed", w:["Slow shutter speed","Wide aperture only","High white balance"], e:"A fast shutter speed captures the subject quickly, freezing motion without blur." },
    { t:"tf", q:"The 3-2-1 backup rule recommends keeping three copies of your files, on two types of media, with one copy stored off-site.", a:"True", e:"The 3-2-1 rule protects photos against loss from theft, damage or drive failure." },
    { t:"tf", q:"Soft, diffused lighting generally produces more flattering portraits than harsh, direct light.", a:"True", e:"Diffused light softens shadows and reduces harsh contrast on the face." },
    { t:"type", q:"Shooting in ______ format instead of JPEG keeps more image data and gives greater flexibility when editing.", a:"RAW", accepts:["raw"], e:"RAW files store uncompressed sensor data, allowing better recovery of detail in editing." },
    { t:"mc", q:"For a photography business, why is it important to back up client photos before deleting them from the camera card?", a:"Lost files cannot be reshot for an event and ruin your reputation", w:["Backups make the camera lighter","It changes the photo colours","It charges the battery faster"], e:"Many events cannot be repeated, so backing up first protects the client and your business." }
  ]},
  { id:"voc_barb", name:"Barbing", emoji:"💈", cards:[
    { t:"mc", q:"Why must clippers, combs and blades be disinfected between every client?", a:"To prevent the spread of skin and scalp infections", w:["To make the clipper run faster","To change the hair colour","To sharpen the blade automatically"], e:"Disinfecting between clients stops germs, fungus and infections from passing on." },
    { t:"mc", q:"What is Barbicide commonly used for in a barbershop?", a:"Disinfecting combs and clipper blades", w:["Styling the hair","Colouring beards","Cooling the clipper motor"], e:"Barbicide is a disinfectant solution barbers use to soak and sanitise tools." },
    { t:"mc", q:"A larger clipper guard number (for example a number 8) produces what result?", a:"Leaves the hair longer", w:["Leaves the hair shorter","Shaves down to the skin","Has no effect on length"], e:"Higher guard numbers leave more hair; lower numbers cut closer to the skin." },
    { t:"mc", q:"What is the key idea behind cutting a fade haircut?", a:"Gradually blending the hair from short to longer with no harsh lines", w:["Leaving sharp visible steps in the hair","Cutting all hair to one length","Using no guards at all"], e:"A fade smoothly blends lengths so there are no obvious lines between them." },
    { t:"mc", q:"How should single-use razor blades be handled after shaving a client?", a:"Discarded once into a sharps container", w:["Reused on the next client","Washed in water and reused for days","Kept loose in a drawer"], e:"Single-use blades are discarded after one client to avoid spreading blood-borne germs." },
    { t:"tf", q:"A clean towel or neck strip should be used for each client to protect their skin and stop germ spread.", a:"True", e:"Fresh towels and neck strips prevent transfer of skin germs between clients." },
    { t:"tf", q:"Clipper blades should be oiled regularly to keep them cutting smoothly and prevent overheating.", a:"True", e:"Oiling reduces friction so blades stay sharp, run cool and last longer." },
    { t:"type", q:"Before disinfecting clippers, you should first remove loose ______ from the blades with a brush.", a:"hair", accepts:["hairs"], e:"Brushing off hair clippings lets the disinfectant reach the blade surfaces properly." },
    { t:"type", q:"Barbers wash and sanitise their ______ before and after each client as a basic hygiene step.", a:"hands", accepts:["hand"], e:"Hand hygiene is a core step that protects both barber and client from infection." },
    { t:"mc", q:"For running a barbing business, why does a tidy, hygienic shop matter?", a:"It builds customer trust and brings repeat clients and referrals", w:["It removes the need for skill","It lets you reuse dirty blades","It makes haircuts free"], e:"Clean, professional shops earn customer confidence, loyalty and word-of-mouth growth." }
  ]},
  { id:"voc_shoe", name:"Shoemaking & Leatherwork", emoji:"👞", cards:[
    { t:"mc", q:"Which leather keeps the full natural grain surface and is the most durable, highest-quality type?", a:"Full-grain leather", w:["Bonded leather","Faux leather","Split suede"], e:"Full-grain leather uses the whole grain layer, making it the strongest and longest-lasting." },
    { t:"mc", q:"What is the saddle stitch known for compared with machine stitching?", a:"If one stitch breaks, the interlocking pattern keeps the seam intact", w:["It unravels completely if one stitch breaks","It can only be done by machine","It uses no thread"], e:"The saddle stitch's interlocking loops make it more durable than a machine lockstitch." },
    { t:"mc", q:"What is an awl used for in leatherwork?", a:"Making or marking stitching holes in the leather", w:["Gluing soles together","Dyeing the leather","Sharpening scissors"], e:"An awl pierces or marks holes so the needle and thread can pass through." },
    { t:"mc", q:"What does a stitching pony (clamp) do for the leatherworker?", a:"Holds the work securely so both hands are free to stitch", w:["Cuts the leather automatically","Colours the edges","Melts the glue"], e:"A stitching pony clamps the piece, freeing both hands and improving stitching speed." },
    { t:"mc", q:"Which adhesive is commonly used to bond leather pieces or soles before stitching?", a:"Contact cement", w:["Wood varnish","Nail polish","Petrol"], e:"Contact cement is applied to both surfaces and bonds firmly once pressed together." },
    { t:"tf", q:"Blunt saddler's needles are preferred for hand stitching because they pass through pre-made holes without piercing new ones.", a:"True", e:"Blunt needles follow the punched holes instead of splitting the leather or the thread." },
    { t:"tf", q:"Waxed thread is used in leatherwork because the wax helps the thread resist abrasion and grip the holes.", a:"True", e:"Waxing strengthens the thread, repels moisture and helps stitches stay tight." },
    { t:"type", q:"An edge ______ is used to smooth and polish (burnish) the cut edges of leather for a neat finish.", a:"slicker", accepts:["burnisher"], e:"An edge slicker rubs the edge until friction heat smooths and seals it." },
    { t:"type", q:"A sharp ______ knife or rotary cutter is used on a cutting mat to cut leather cleanly to shape.", a:"craft", accepts:["utility","head","cutting"], e:"A sharp knife on a cutting mat gives clean, accurate edges and protects the work surface." },
    { t:"mc", q:"For a leatherwork business, why is consistent stitch spacing and neat edges important?", a:"Clean, even finishing signals quality and lets you charge more", w:["It makes the leather waterproof for life","It removes the need for good leather","It means you can skip gluing"], e:"Professional finishing raises perceived value, helping you win and keep paying customers." }
  ]},
  { id:"voc_ac", name:"AC & Refrigeration Repair", emoji:"❄️", cards:[
    { t:"mc", q:"Why can liquid refrigerant cause frostbite if it contacts the skin?", a:"It boils at a very low temperature and freezes skin on contact", w:["It is acidic like battery acid","It is electrically live","It is radioactive"], e:"Refrigerant has a very low boiling point, so it absorbs heat fast and can freeze tissue." },
    { t:"mc", q:"Which PPE protects the eyes from a refrigerant splash during service?", a:"Safety goggles or a face shield", w:["Sunglasses","A cloth headband","Reading glasses"], e:"Goggles or a face shield guard against liquid refrigerant, which can freeze the cornea." },
    { t:"mc", q:"Why is good ventilation important when working with refrigerants in an enclosed space?", a:"Refrigerant is heavier than air and can displace oxygen, risking asphyxiation", w:["It makes the room smell nice","It speeds up the compressor","It charges the system faster"], e:"Refrigerant pools and pushes out air in confined spaces, which can suffocate workers." },
    { t:"mc", q:"What is the part that compresses the refrigerant and circulates it through the system called?", a:"Compressor", w:["Thermostat","Capacitor","Drain pan"], e:"The compressor pressurises and pumps refrigerant around the cooling cycle." },
    { t:"mc", q:"Which component releases heat to the outside air as the refrigerant condenses?", a:"Condenser", w:["Evaporator","Compressor","Filter drier"], e:"The condenser sheds the absorbed heat outdoors, turning refrigerant from gas to liquid." },
    { t:"tf", q:"Refrigerant should be recovered into proper equipment and never deliberately vented into the atmosphere.", a:"True", e:"Venting refrigerant harms the environment and is illegal in many places; it must be recovered." },
    { t:"tf", q:"Some modern refrigerants such as R-600a (isobutane) and R-290 (propane) are flammable, so no open flames or sparks should be near a leak.", a:"True", e:"Hydrocarbon refrigerants can ignite, so ignition sources must be kept away during service." },
    { t:"type", q:"A set of manifold ______ is used to read system pressures during diagnosis and charging.", a:"gauges", accepts:["gauge"], e:"Manifold gauges show high and low side pressures, helping diagnose the system." },
    { t:"mc", q:"A common cause of an AC not cooling well is which of these?", a:"Low refrigerant from a leak or a dirty/blocked filter", w:["Too much sunlight on the remote","The wall colour","A full water glass nearby"], e:"Low charge from leaks and blocked filters are frequent reasons for poor cooling." },
    { t:"mc", q:"Before opening or working inside an AC unit's electrical parts, what should you do first?", a:"Switch off and isolate the power supply", w:["Pour water on it","Turn it to maximum cooling","Remove the customer's furniture"], e:"Isolating power prevents electric shock while working on the unit." }
  ]},
  { id:"voc_paint", name:"Painting & Decorating", emoji:"🖌️", cards:[
    { t:"mc", q:"What is the main purpose of applying a primer before the topcoat?", a:"To seal the surface and help the paint stick and last", w:["To make the wall slippery","To replace the need for cleaning","To remove the need for any topcoat"], e:"Primer seals and grips the surface, improving adhesion and the finish of the topcoat." },
    { t:"mc", q:"Why is surface preparation (cleaning, sanding, filling) important before painting?", a:"Paint adheres better and gives a smoother, longer-lasting finish", w:["It makes the paint dry slower only","It changes the paint's colour","It is never necessary"], e:"A clean, smooth, sound surface lets paint bond and look professional." },
    { t:"mc", q:"Which tool is best for quickly covering a large flat wall area with paint?", a:"Roller", w:["Fine artist's brush","Putty knife","Screwdriver"], e:"A roller spreads paint fast and evenly over large flat surfaces." },
    { t:"mc", q:"What is emulsion (water-based) paint commonly used for?", a:"Interior walls and ceilings", w:["Welding metal","Lubricating engines","Sealing water pipes"], e:"Water-based emulsion is the usual choice for interior walls and ceilings." },
    { t:"mc", q:"Why should you ventilate a room and avoid breathing fumes while painting, especially with solvent-based paint?", a:"The fumes can cause dizziness, headaches and breathing irritation", w:["Fumes make paint dry the wrong colour","Ventilation wastes paint","Fumes improve eyesight"], e:"Good airflow disperses harmful solvent vapours that can make you ill." },
    { t:"tf", q:"Masking tape and drop cloths (dust sheets) are used to protect edges and floors from paint splashes.", a:"True", e:"Masking and covering surfaces keeps lines clean and prevents staining floors and fittings." },
    { t:"tf", q:"When using a ladder to paint high areas, it should be placed on firm, level ground and not overreached from.", a:"True", e:"A stable ladder and avoiding overreaching prevent dangerous falls." },
    { t:"type", q:"Cracks and holes in a wall are filled with ______ and sanded smooth before painting.", a:"filler", accepts:["putty","wall filler"], e:"Filler levels defects so the painted surface looks even." },
    { t:"type", q:"A paint ______ (or tray and brush) is used to apply emulsion smoothly to large wall surfaces.", a:"roller", accepts:["brush"], e:"A roller loaded from a tray gives quick, even coverage on walls." },
    { t:"mc", q:"For a painting business, why is it good practice to estimate the area and number of coats before quoting?", a:"It lets you price paint and labour accurately and avoid losses", w:["It changes the colour of the paint","It removes the need for primer","It makes the job take longer on purpose"], e:"Measuring area and coats gives a fair, profitable quote and avoids underpricing." }
  ]},
  { id:"voc_event", name:"Event Decoration", emoji:"🎈", cards:[
    { t:"mc", q:"What should an event decorator do first when planning a decoration job?", a:"Understand the client's theme, colours, venue and budget", w:["Buy random balloons immediately","Pick colours without asking","Ignore the venue size"], e:"Clarifying theme, colours, venue and budget up front guides every later decision." },
    { t:"mc", q:"Which colours are described as complementary and create strong contrast in a colour scheme?", a:"Colours opposite each other on the colour wheel", w:["Colours next to each other only","Only shades of grey","Random unrelated colours"], e:"Complementary colours sit opposite on the wheel and make each other stand out." },
    { t:"mc", q:"What is draping commonly used for in event decoration?", a:"Covering walls, ceilings or tables with flowing fabric for an elegant look", w:["Cooking the event food","Wiring the sound system","Parking the guests' cars"], e:"Draping uses fabric to soften and beautify spaces and hide plain backgrounds." },
    { t:"mc", q:"When building a balloon arch, what helps it hold its shape and stay secure?", a:"A frame or strong base and properly sized, evenly inflated balloons", w:["Leaving balloons half flat","Using no support at all","Only one giant balloon"], e:"A frame plus consistent inflation keeps an arch stable and neat." },
    { t:"mc", q:"Why is preparing a budget important before buying decoration materials?", a:"It keeps spending under control and protects your profit", w:["It makes the event longer","It changes the venue automatically","It removes the need for a theme"], e:"A budget prevents overspending so the job stays profitable for the decorator." },
    { t:"tf", q:"Visiting or measuring the venue beforehand helps plan how much material is needed and how the layout will work.", a:"True", e:"A site visit reveals dimensions, fixings and access so plans fit the real space." },
    { t:"tf", q:"Confirming the setup and takedown times with the venue avoids clashing with other events and last-minute stress.", a:"True", e:"Agreed access times let the team set up and clear out smoothly." },
    { t:"type", q:"A focal point such as the ______ table or stage is usually decorated most heavily to draw guests' attention.", a:"head", accepts:["main","high","cake","bridal"], e:"Concentrating decor on a focal point like the head table creates visual impact." },
    { t:"type", q:"Balloons can be inflated faster and more evenly using an electric ______ instead of by mouth.", a:"pump", accepts:["air pump","inflator","balloon pump"], e:"An electric pump inflates many balloons quickly to a consistent size." },
    { t:"mc", q:"For client care in an event business, why should you confirm the final design and price in writing?", a:"It prevents misunderstandings and disputes on the event day", w:["It lets you ignore the theme","It means you need no materials","It guarantees free balloons"], e:"A written agreement sets clear expectations and protects both you and the client." }
  ]},
  { id:"voc_soap", name:"Soap & Cosmetics Making", emoji:"🧼", cards:[
    { t:"mc", q:"When mixing lye solution, which is the correct and safe order?", a:"Add the lye slowly to the water", w:["Add water to the lye quickly","Mix lye and water in any order","Heat the lye over a flame first"], e:"Adding lye to water controls the heat; doing it the other way can cause a dangerous eruption." },
    { t:"mc", q:"What PPE should always be worn when handling lye (sodium hydroxide)?", a:"Goggles and chemical-resistant gloves", w:["Only a paper hat","Open sandals and shorts","No protection is needed"], e:"Lye is highly caustic and can cause severe burns, so eyes and skin must be protected." },
    { t:"mc", q:"Why must lye be mixed in a well-ventilated area?", a:"Mixing releases fumes that can irritate the lungs and eyes", w:["It makes the soap smell better","Fumes help the soap set","Ventilation changes the colour"], e:"The reaction gives off irritating fumes that should not be inhaled." },
    { t:"mc", q:"What is the chemical reaction between lye and oils that produces soap called?", a:"Saponification", w:["Evaporation","Condensation","Fermentation"], e:"Saponification is the reaction where lye and fats combine to form soap and glycerin." },
    { t:"mc", q:"Why do soap makers use a lye calculator and accurate scale for their recipes?", a:"To get the correct lye-to-oil ratio so no harmful excess lye remains", w:["To make the soap heavier","To skip the curing step","To avoid wearing gloves"], e:"Precise measuring ensures all the lye reacts, leaving a safe, balanced bar." },
    { t:"tf", q:"If lye solution splashes on the skin, it should be rinsed immediately with plenty of cool running water.", a:"True", e:"Flushing with lots of water quickly dilutes and removes the caustic lye to limit burns." },
    { t:"tf", q:"Cold-process soap needs to cure for several weeks so it becomes milder, harder and longer-lasting.", a:"True", e:"Curing lets excess water evaporate and the bar finish hardening into a gentle soap." },
    { t:"type", q:"Lye should be stored in a sealed, clearly ______ container, away from children, food and moisture.", a:"labelled", accepts:["labeled","marked"], e:"Clear labelling and secure storage prevent dangerous mix-ups and accidental contact." },
    { t:"type", q:"Equipment used for lye and soap should be heat-resistant and made of stainless steel or ______, never aluminium.", a:"plastic", accepts:["glass","silicone"], e:"Lye reacts with aluminium, so non-reactive materials like stainless steel or plastic are used." },
    { t:"mc", q:"For a soap business, why does clean, clearly labelled packaging with ingredients matter?", a:"It builds customer trust, informs allergies and looks professional", w:["It lets you skip curing the soap","It makes the soap caustic","It removes the need for hygiene"], e:"Good labelling and packaging reassure buyers, meet expectations and help sell the product." }
  ]}
];
window.LESSONS = window.LESSONS || {};
window.LESSONS.va = { name:"Virtual Assistant", emoji:"🗂️", items:[
  { t:"What a VA Does and Who Hires Them", intro:"A virtual assistant handles administrative, technical, or creative tasks for clients remotely. Knowing the scope helps you pitch the right services.", points:[
    "A VA supports busy people by handling email, scheduling, data entry, research, social media, and customer replies",
    "Common clients are solo entrepreneurs, coaches, real estate agents, small e-commerce shops, and busy executives",
    "You can be a generalist or specialise (for example a social media VA, a real estate VA, or an executive assistant)",
    "Most VAs work fully remote, so a reliable laptop and stable internet are your core requirements",
    "You do not need a degree to start, only practical skills, reliability, and clear communication",
    "Demand is strong because hiring a VA is cheaper for clients than a full-time staff member"
  ]},
  { t:"Core Tools Every VA Should Know", intro:"Clients expect you to already know the everyday tools that run a small business. Learn a handful well rather than many poorly.", points:[
    "Master email and a calendar app (Gmail and Google Calendar, or Outlook) for scheduling and reminders",
    "Learn Google Workspace (Docs, Sheets, Drive) and the Microsoft equivalents (Word, Excel, OneDrive)",
    "Use a scheduling tool like Calendly to let clients book time without back-and-forth emails",
    "Manage tasks and projects with Trello or Asana so nothing falls through the cracks",
    "Use Slack or Zoom for team chat and video calls, and a password manager so you never see raw client passwords",
    "AI tools like ChatGPT, Claude, or Gemini can speed up drafting emails, summaries, and research, but always check the output before sending"
  ]},
  { t:"Communication and Professionalism", intro:"Clients judge you on how clearly and reliably you communicate. Good communication often matters more than perfect skills.", points:[
    "Reply within agreed hours and confirm you received a task, even if you cannot finish it yet",
    "Write short, clear messages with a subject, the key point first, and any deadline stated plainly",
    "Ask questions early instead of guessing, and confirm instructions before starting big tasks",
    "Give proactive updates so the client never has to chase you to ask where things stand",
    "Keep client information private and never share passwords, files, or details with outsiders",
    "Stay calm and polite even with difficult feedback, and own your mistakes with a fix rather than excuses"
  ]},
  { t:"Time Management and Productivity", intro:"As a VA you manage your own hours and often several clients at once. Systems keep you from missing deadlines.", points:[
    "Plan tomorrow at the end of each day so you start with a clear priority list",
    "Batch similar tasks together (for example answer all emails at set times) to avoid constant switching",
    "Use a time tracker like Toggl or Clockify to see where hours go and to bill accurately",
    "Block focus time and turn off notifications so deep tasks actually get finished",
    "Separate urgent from important, and tackle the high-value work before small busywork",
    "Set realistic deadlines with buffer time, and never promise faster than you can reliably deliver"
  ]},
  { t:"Getting Clients and Getting Paid", intro:"Finding work and handling money professionally turns VA skills into real income. Start small and build proof.", points:[
    "Create profiles on freelance platforms like Upwork and Fiverr, and use LinkedIn to reach clients directly",
    "Write a clear profile that names your services, tools, and the result you give clients, not just your job title",
    "Price by the hour when starting, or move to packages and retainers once you know how long tasks take",
    "Research typical rates for your service and region instead of guessing, and raise rates as you gain reviews",
    "Send a simple written agreement covering scope, hours, rate, and payment terms before you begin",
    "Invoice on time using a tool like Wave or PayPal, state your due date clearly, and keep records for tax"
  ]}
]};
window.LESSONS.pm = { name:"Product Management", emoji:"📐", items:[
  { t:"What a Product Manager Does", intro:"A product manager decides what to build and why, then guides a team to deliver it. The PM connects users, business goals, and the build team.", points:[
    "A PM owns the product vision and roadmap, deciding which problems to solve and in what order",
    "You do not usually code or design yourself, you align engineers, designers, and stakeholders around a shared goal",
    "Your job is to understand the user problem deeply, not to fall in love with one solution",
    "PMs spend their time on discovery (research), prioritisation, writing requirements, and reviewing results",
    "Good PMs say no often, because protecting focus is how you ship value instead of a pile of half-features",
    "Core skills are communication, prioritisation, basic data literacy, and empathy for the user"
  ]},
  { t:"Understanding Users and Problems", intro:"Great products start with a real, well-understood problem. Talking to users beats guessing from your desk.", points:[
    "Interview real or potential users and ask about their problems and habits, not whether they like your idea",
    "Ask open questions about what they did recently, because past behaviour is more honest than predictions",
    "Look for the pain point behind a feature request, since users describe solutions but you must find the need",
    "Write a clear problem statement that names the user, their situation, and the outcome they want",
    "Use simple user personas and a basic user journey to see where people get stuck",
    "Combine what users say (interviews) with what users do (data) before you commit to building"
  ]},
  { t:"MVP and Prioritisation with MoSCoW", intro:"You can never build everything at once, so you ship the smallest version that delivers value and learn from it. MoSCoW keeps the team focused.", points:[
    "An MVP (minimum viable product) is the smallest release that solves the core problem and lets you learn fast",
    "MoSCoW sorts work into Must have, Should have, Could have, and Will not have for now",
    "Must have items are critical, the release fails without them, so they take the largest share of effort",
    "Should have items are important but can wait, and Could have items are nice extras if time allows",
    "Will not have items are agreed out of scope this round, which protects you from scope creep",
    "Avoid the common trap of marking everything Must have, and revisit priorities as you learn more"
  ]},
  { t:"Agile and Scrum Basics", intro:"Most product teams work in short, repeating cycles instead of one big launch. Scrum is the most common version of this.", points:[
    "Agile means building in small increments, getting feedback, and adapting rather than planning everything upfront",
    "Scrum organises work into sprints, which are short fixed periods, often one to two weeks",
    "The product backlog is the ordered list of everything you might build, kept prioritised by the product owner",
    "Each sprint the team pulls top backlog items into a sprint plan and aims to finish them",
    "A short daily stand-up keeps the team aligned on progress and blockers",
    "End each sprint with a review of what shipped and a retrospective on how to work better next time"
  ]},
  { t:"Metrics, Launch, and Retention", intro:"After launch, data tells you whether the product actually works. Pick a few meaningful numbers instead of tracking everything.", points:[
    "A KPI is a key performance indicator, the few numbers that show if you are hitting your goal",
    "Common metrics include active users, conversion rate, retention rate, and churn (the rate users leave)",
    "Retention (do users come back) usually matters more than a one-time spike in sign-ups",
    "Pick one main metric for a goal so the team is not pulled in many directions at once",
    "Watch out for vanity metrics that look good but do not reflect real value, like raw page views",
    "Treat launch as a start, not the finish, and use feedback and data to improve the next version"
  ]}
]};
window.LESSONS.cc = { name:"Content Creation", emoji:"🎬", items:[
  { t:"Choosing a Niche and Platform", intro:"A clear niche helps the right audience find and follow you. The platform you pick should match your content style and goals.", points:[
    "Pick a niche where your interest, your skill, and audience demand overlap so you can keep posting consistently",
    "A focused niche grows faster than a general account because the algorithm and viewers know what to expect",
    "Match the format to the platform, short video suits TikTok, Instagram Reels, and YouTube Shorts",
    "YouTube rewards long-form and search-driven content with a longer shelf life, while TikTok drives fast reach",
    "Instagram leans on visuals and personal branding, and a newsletter or blog gives you an audience you own",
    "Start on one or two platforms, then repurpose the same content to others once you have a rhythm"
  ]},
  { t:"Hooks and Scripting", intro:"The first few seconds decide whether someone keeps watching or scrolls away. A simple script keeps your message tight.", points:[
    "Open with a strong hook in the first three seconds that names a benefit, a question, or a surprising claim",
    "Make a clear promise early, telling viewers what they will gain by staying",
    "Keep one core idea per piece of content rather than cramming in several",
    "Use a simple structure of hook, value or story, then a call to action",
    "Write the way you talk so it sounds natural when spoken aloud",
    "End by telling viewers exactly what to do next, such as follow, comment, or watch another video"
  ]},
  { t:"Filming and Editing Basics", intro:"You do not need expensive gear to start, your phone is enough. Good light and clear sound matter more than a fancy camera.", points:[
    "Film in good light, with natural window light or a cheap ring light facing you, never behind you",
    "Clear audio matters most, so record in a quiet space and use earphones with a mic if you can",
    "Hold the phone steady with a tripod or a stable surface, and shoot vertical for short-form video",
    "Edit on free or low-cost apps like CapCut, DaVinci Resolve, or InShot to trim and add captions",
    "Add captions because many people watch with the sound off, and captions boost retention",
    "Keep cuts tight, remove long pauses, and aim to hold attention from the first second to the last"
  ]},
  { t:"Posting Consistently and Getting Found", intro:"Consistency trains both the algorithm and your audience to expect you. Smart use of search and tags helps new people discover you.", points:[
    "Set a realistic schedule you can keep, such as three posts a week, rather than burning out in week one",
    "Batch-create several pieces in one session and schedule them so a busy day never breaks your streak",
    "Use clear titles and keywords so your content shows up in search, which matters a lot on YouTube",
    "Add a few relevant hashtags and on-screen text to help platforms understand and recommend your content",
    "Reply to comments early, since engagement in the first hour signals the algorithm to show it more",
    "Track which posts perform best and make more of what works instead of guessing"
  ]},
  { t:"Monetisation and Copyright", intro:"Income usually comes from several streams, not one. Knowing the rules keeps your account safe from strikes.", points:[
    "Common income streams are platform ad revenue, brand sponsorships, affiliate marketing, and selling your own products",
    "Most creators combine three or four streams so one algorithm change does not wipe out their income",
    "Ad programs have entry rules, for example the YouTube Partner Program requires a minimum of subscribers and watch hours",
    "You can earn from sponsorships and affiliates even with a small but engaged audience, often called micro-creators",
    "A short media kit showing your audience and engagement helps you pitch brands and land deals",
    "Only use music, clips, and images you own or are licensed to use, and always disclose paid promotions to stay legal"
  ]}
]};
